window.QBANK=[{"id": "0-1", "ch": 0, "n": 1, "stem": "Quale antibiotico è attivo <strong>solo</strong> sui batteri Gram-positivi?", "opts": ["Gentamicina", "Vancomicina", "Meropenem", "Ciprofloxacina"], "a": 1, "sec": ["2.2"]}, {"id": "0-2", "ch": 0, "n": 2, "stem": "Quale antibiotico è attivo su <em>Pseudomonas aeruginosa</em>?", "opts": ["Ceftriaxone", "Amoxicillina", "Clindamicina", "Piperacillina-tazobactam"], "a": 3, "sec": ["2.2", "2.3"]}, {"id": "0-3", "ch": 0, "n": 3, "stem": "La daptomicina non deve essere usata per trattare la polmonite perché:", "opts": ["È inattivata dal surfattante polmonare", "Non copre MRSA", "Non è disponibile per via endovenosa", "È solo batteriostatica"], "a": 0, "sec": ["2.2", "3.2"]}, {"id": "0-4", "ch": 0, "n": 4, "stem": "L'indice PK/PD che meglio predice l'efficacia dei β-lattamici è:", "opts": ["Cmax/MIC", "AUC<sub>24</sub>/MIC", "La percentuale dell'intervallo tra le dosi con concentrazione libera sopra la MIC (%fT&gt;MIC)", "La durata dell'effetto post-antibiotico"], "a": 2, "sec": ["6.2"]}, {"id": "0-5", "ch": 0, "n": 5, "stem": "La somministrazione degli aminoglicosidi una volta al giorno è giustificata soprattutto perché:", "opts": ["Gli aminoglicosidi sono antibiotici tempo-dipendenti senza effetto post-antibiotico", "Gli aminoglicosidi sono ben assorbiti per via orale", "L'uccisione è concentrazione-dipendente e l'effetto post-antibiotico è lungo, mentre la tossicità è minore con un intervallo lungo tra le dosi", "Gli aminoglicosidi si accumulano nel liquor"], "a": 2, "sec": ["6.1", "6.2"]}, {"id": "0-6", "ch": 0, "n": 6, "stem": "Il monitoraggio terapeutico dei farmaci (TDM) è più utile per gli antibiotici che:", "opts": ["Hanno una finestra terapeutica stretta, come vancomicina e aminoglicosidi", "Sono ben assorbiti per via orale", "Sono eliminati soprattutto con la bile", "Hanno un ampio margine di sicurezza, come le penicilline"], "a": 0, "sec": ["6.5"]}, {"id": "0-7", "ch": 0, "n": 7, "stem": "Un paziente traumatizzato di 25 anni con sepsi in terapia intensiva ha una clearance della creatinina di 180 ml/min. La conseguenza più probabile per la terapia con β-lattamici a dosi standard è:", "opts": ["Accumulo e neurotossicità", "Concentrazioni subterapeutiche per la clearance renale aumentata", "Nessuna variazione dell'esposizione", "Aumento del legame proteico"], "a": 1, "sec": ["6.3"]}, {"id": "0-8", "ch": 0, "n": 8, "stem": "Gli Enterobacterales resistenti ai carbapenemi (CRE) preoccupano soprattutto perché:", "opts": ["Sono resistenti solo alle penicilline", "Si trattano in modo affidabile con il ceftriaxone", "Si osservano solo in comunità", "Sono resistenti a quasi tutti i β-lattamici e lasciano poche opzioni terapeutiche"], "a": 3, "sec": ["5.2"]}, {"id": "0-9", "ch": 0, "n": 9, "stem": "Un'infezione grave del torrente ematico da <em>E. coli</em> produttore di ESBL si tratta di solito con:", "opts": ["Ceftriaxone", "Amoxicillina", "Ampicillina", "Un carbapenemico"], "a": 3, "sec": ["5.2", "5.4"]}, {"id": "0-10", "ch": 0, "n": 10, "stem": "Il più forte fattore di rischio singolo per l'infezione da un determinato microrganismo multiresistente è:", "opts": ["L'età superiore a 65 anni", "Una precedente colonizzazione o infezione da quel microrganismo", "Il diabete", "Il sesso femminile"], "a": 1, "sec": ["5.3"]}, {"id": "0-11", "ch": 0, "n": 11, "stem": "La de-escalation della terapia antibiotica consiste nel:", "opts": ["Restringere lo spettro o ridurre il numero di antibiotici una volta noti i risultati delle colture", "Aumentare la dose dell'antibiotico in corso", "Aggiungere un secondo antibiotico", "Passare dalla terapia orale a quella endovenosa"], "a": 0, "sec": ["7.2"]}, {"id": "0-12", "ch": 0, "n": 12, "stem": "Un microrganismo multiresistente (MDR) è definito come non sensibile a:", "opts": ["Un solo antibiotico", "La sola penicillina", "Almeno un agente in tre o più categorie di antimicrobici", "Tutti gli antibiotici disponibili"], "a": 2, "sec": ["5.1"]}, {"id": "0-13", "ch": 0, "n": 13, "stem": "Secondo le linee guida attuali sulla sepsi, in un paziente con shock settico gli antibiotici vanno somministrati:", "opts": ["Immediatamente, idealmente entro 1 ora dal riconoscimento", "Entro 3 ore, dopo l'imaging", "Dopo il risultato della procalcitonina", "Solo dopo i risultati delle emocolture"], "a": 0, "sec": ["4.1"]}, {"id": "0-14", "ch": 0, "n": 14, "stem": "Quale delle seguenti <strong>non</strong> è una motivazione accettata per la terapia antibiotica di associazione?", "opts": ["Sinergia nell'endocardite da <em>Enterococcus faecalis</em>", "Soppressione delle tossine con la clindamicina nella fascite necrotizzante", "Prevenzione delle resistenze nella tubercolosi", "Trattamento definitivo di routine di una batteriemia da <em>E. coli</em> pienamente sensibile"], "a": 3, "sec": ["4.4"]}, {"id": "0-15", "ch": 0, "n": 15, "stem": "In molte infezioni comuni (ad es. polmonite comunitaria, batteriemia da Gram-negativi non complicata), i cicli antibiotici brevi rispetto a quelli più lunghi:", "opts": ["Sono meno efficaci", "Sono altrettanto efficaci, con meno effetti avversi", "Aumentano la resistenza antimicrobica", "Non sono mai appropriati"], "a": 1, "sec": ["7.4"]}, {"id": "0-16", "ch": 0, "n": 16, "stem": "Quale antibiotico ha un'eccellente biodisponibilità orale, che consente un passaggio precoce dalla via e.v. alla via orale con livelli ematici simili?", "opts": ["Vancomicina", "Ceftriaxone", "Linezolid", "Gentamicina"], "a": 2, "sec": ["3.3", "7.3"]}, {"id": "0-17", "ch": 0, "n": 17, "stem": "Nella classificazione AWaRe, quale antibiotico appartiene al gruppo <strong>Reserve</strong>?", "opts": ["Amoxicillina", "Ciprofloxacina", "Colistina", "Ceftriaxone"], "a": 2, "sec": ["2.6"]}, {"id": "0-18", "ch": 0, "n": 18, "stem": "Un paziente riferisce un esantema lieve, non orticarioide, con amoxicillina 20 anni fa e ora deve essere trattato per una pielonefrite. L'affermazione più appropriata è:", "opts": ["Di solito si può somministrare un β-lattamico con catena laterale diversa; l'etichetta di allergia va valutata", "Tutti i β-lattamici sono assolutamente controindicati", "I carbapenemi hanno un rischio di reattività crociata del 50%", "Si può usare solo la vancomicina"], "a": 0, "sec": ["4.2"]}, {"id": "0-19", "ch": 0, "n": 19, "stem": "Quale antibiotico è appropriato per un patogeno intracellulare come <em>Legionella pneumophila</em>?", "opts": ["Ceftriaxone", "Amoxicillina", "Vancomicina", "Levofloxacina"], "a": 3, "sec": ["2.3", "3.2"]}, {"id": "0-20", "ch": 0, "n": 20, "stem": "In un antibiogramma refertato con gli attuali breakpoint europei, la categoria \"I\" significa:", "opts": ["Intermedio: il farmaco va evitato", "Sensibile, esposizione aumentata", "Resistenza intrinseca", "Dati insufficienti per l'interpretazione"], "a": 1, "sec": ["2.5"]}, {"id": "1-1", "ch": 1, "n": 1, "stem": "Secondo Sepsis-3, la sepsi è definita come:", "opts": ["Infezione più almeno 2 criteri SIRS", "Disfunzione d'organo potenzialmente letale causata da una risposta disregolata dell'ospite all'infezione", "Batteriemia con emocoltura positiva", "Infezione con ipotensione non responsiva ai fluidi"], "a": 1, "sec": ["2.1", "5.1"]}, {"id": "1-2", "ch": 1, "n": 2, "stem": "Quale combinazione identifica lo shock settico in un adulto secondo Sepsis-3?", "opts": ["Pressione arteriosa sistolica &lt;90 mmHg e frequenza cardiaca &gt;90/min", "qSOFA ≥2 e febbre", "Lattato &gt;4 mmol/l, indipendentemente dalla pressione arteriosa", "Vasopressori necessari per mantenere una PAM ≥65 mmHg e lattato &gt;2 mmol/l nonostante un adeguato riempimento volemico"], "a": 3, "sec": ["5.1"]}, {"id": "1-3", "ch": 1, "n": 3, "stem": "Quali sono i tre criteri del qSOFA?", "opts": ["Frequenza respiratoria ≥22/min, alterazione dello stato mentale, pressione arteriosa sistolica ≤100 mmHg", "Temperatura &gt;38 °C, frequenza cardiaca &gt;90/min, globuli bianchi &gt;12.000/µl", "Lattato &gt;2 mmol/l, oliguria, piastrine &lt;100.000/µl", "PaO₂/FiO₂ &lt;300, creatinina &gt;2 mg/dl, bilirubina &gt;2 mg/dl"], "a": 0, "sec": ["5.1"]}, {"id": "1-4", "ch": 1, "n": 4, "stem": "Per lo screening della sepsi negli adulti ricoverati le linee guida attuali raccomandano:", "opts": ["Il qSOFA come unico strumento preferito", "Il dosaggio della procalcitonina in tutti i pazienti febbrili", "NEWS, NEWS2, MEWS o SIRS rispetto al qSOFA come singolo strumento di screening", "Nessuno screening, solo il giudizio clinico"], "a": 2, "sec": ["5.2"]}, {"id": "1-5", "ch": 1, "n": 5, "stem": "La fonte più frequente di sepsi nell'adulto è:", "opts": ["Le vie urinarie", "Il sistema nervoso centrale", "I polmoni", "La cute"], "a": 2, "sec": ["1.1"]}, {"id": "1-6", "ch": 1, "n": 6, "stem": "Una donna di 72 anni si presenta con febbre, dolore al fianco, confusione e ipotensione. L'esame delle urine mostra leucociti e nitriti. Il patogeno più probabile è:", "opts": ["<em>Escherichia coli</em>", "<em>Streptococcus pyogenes</em>", "<em>Neisseria meningitidis</em>", "<em>Candida albicans</em>"], "a": 0, "sec": ["1.1"]}, {"id": "1-7", "ch": 1, "n": 7, "stem": "Quale affermazione sull'iperlattatemia nella sepsi è corretta?", "opts": ["È sempre causata da ipossia tissutale", "Non si osserva mai nei pazienti con pressione arteriosa normale", "Non ha valore prognostico", "Può derivare anche dalla stimolazione β2-adrenergica della glicolisi aerobia e dalla ridotta clearance epatica"], "a": 3, "sec": ["3.5"]}, {"id": "1-8", "ch": 1, "n": 8, "stem": "Quale reperto è tipico dell'immunosoppressione indotta dalla sepsi?", "opts": ["Aumentata espressione di HLA-DR sui monociti", "Apoptosi dei linfociti e ridotta espressione di HLA-DR sui monociti", "Aumento delle cellule dendritiche circolanti", "Assenza di citochine antinfiammatorie"], "a": 1, "sec": ["3.2"]}, {"id": "1-9", "ch": 1, "n": 9, "stem": "Un paziente con polmonite è ipoteso e richiede noradrenalina. Secondo le linee guida attuali gli antimicrobici vanno somministrati:", "opts": ["Subito, idealmente entro 1 ora dal riconoscimento", "Entro 3 ore, dopo un iter diagnostico completo", "Solo dopo la positivizzazione dell'emocoltura", "Entro 6 ore, quando è disponibile la procalcitonina"], "a": 0, "sec": ["6.2"]}, {"id": "1-10", "ch": 1, "n": 10, "stem": "Un paziente con febbre e tachicardia borderline, senza ipotensione e senza una fonte evidente, ha una sepsi possibile. Le linee guida attuali suggeriscono:", "opts": ["Antimicrobici subito, prima di qualsiasi valutazione", "Nessun antimicrobico per almeno 24 ore", "Una valutazione rapida e limitata nel tempo, poi antimicrobici entro 3 ore se il sospetto di infezione persiste", "Iniziare gli antimicrobici solo se la procalcitonina è elevata"], "a": 2, "sec": ["6.2"]}, {"id": "1-11", "ch": 1, "n": 11, "stem": "Quale affermazione sulle emocolture nella sepsi è corretta?", "opts": ["Un solo set è sufficiente", "Vanno prelevate solo dopo la prima dose di antibiotico", "Non servono se la fonte è evidente", "Vanno prelevati almeno 2 set prima degli antimicrobici, senza ritardare la terapia antimicrobica"], "a": 3, "sec": ["5.3"]}, {"id": "1-12", "ch": 1, "n": 12, "stem": "Il vasopressore di prima linea nello shock settico dell'adulto è:", "opts": ["Dopamina", "Noradrenalina", "Vasopressina", "Fenilefrina"], "a": 1, "sec": ["6.6"]}, {"id": "1-13", "ch": 1, "n": 13, "stem": "L'obiettivo iniziale raccomandato di pressione arteriosa media nello shock settico dell'adulto è:", "opts": ["55 mmHg", "65 mmHg", "80–85 mmHg", "100 mmHg"], "a": 1, "sec": ["6.6"]}, {"id": "1-14", "ch": 1, "n": 14, "stem": "Quale fluido è preferito per la rianimazione iniziale di un paziente con shock settico senza lesione cerebrale?", "opts": ["Idrossietilamido", "Albumina al 20% da sola", "Cristalloide bilanciato (ad es. Ringer lattato)", "Glucosio al 5%"], "a": 2, "sec": ["6.5"]}, {"id": "1-15", "ch": 1, "n": 15, "stem": "Nell'ipoperfusione indotta dalla sepsi le linee guida attuali suggeriscono un volume iniziale di cristalloidi di:", "opts": ["Almeno 30 ml/kg nelle prime 3 ore", "5 ml/kg in 24 ore", "100 ml/kg nella prima ora", "Nessun fluido finché non è posizionato un catetere venoso centrale"], "a": 0, "sec": ["6.5"]}, {"id": "1-16", "ch": 1, "n": 16, "stem": "Quale affermazione sulla vitamina C endovenosa nella sepsi è corretta?", "opts": ["È raccomandata in tutti i pazienti con shock settico", "È il trattamento di prima linea dell'acidosi lattica", "Dimezza la mortalità nello shock settico", "Le linee guida la sconsigliano, perché le evidenze randomizzate non hanno mostrato benefici e un possibile danno"], "a": 3, "sec": ["6.8"]}, {"id": "1-17", "ch": 1, "n": 17, "stem": "Un paziente con shock settico ha un rene ostruito e infetto (calcolo con idronefrosi). L'approccio migliore è:", "opts": ["Solo antibiotici per 14 giorni, poi consulenza urologica programmata", "Attendere i risultati delle emocolture prima di qualsiasi intervento", "Corticosteroidi al posto degli antibiotici", "Antibiotici più decompressione urgente, idealmente entro 6 ore dalla diagnosi"], "a": 3, "sec": ["6.4"]}, {"id": "1-18", "ch": 1, "n": 18, "stem": "Nei pazienti ricoverati clinicamente stabili con infezione del torrente ematico non complicata (senza immunosoppressione grave né focolai che richiedano una terapia prolungata):", "opts": ["7 giorni di antibiotici sono efficaci quanto 14 giorni", "14 giorni di antibiotici riducono la mortalità rispetto a 7 giorni", "3 giorni di antibiotici sono efficaci quanto 14 giorni", "Sono efficaci solo 6 settimane di terapia endovenosa"], "a": 0, "sec": ["7.1"]}, {"id": "1-19", "ch": 1, "n": 19, "stem": "Secondo i criteri attuali di sepsi pediatrica, lo shock settico nel bambino è definito come:", "opts": ["Qualsiasi bambino con febbre e tachicardia", "SIRS più ipotensione", "Sepsi (Phoenix Sepsis Score ≥2) con almeno 1 punto cardiovascolare", "Emocoltura positiva e lattato &gt;2 mmol/l"], "a": 2, "sec": ["5.4"]}, {"id": "1-20", "ch": 1, "n": 20, "stem": "Quale affermazione sul decorso a lungo termine dopo una sepsi è corretta?", "opts": ["I sopravvissuti tornano allo stato di salute precedente entro un mese", "I sopravvissuti sono a rischio di compromissione fisica, cognitiva e psicologica e di nuovi ricoveri, spesso per infezione", "Il follow-up non serve una volta sospesi gli antibiotici", "Il deterioramento cognitivo dopo la sepsi è sempre reversibile in pochi giorni"], "a": 1, "sec": ["7.2"]}, {"id": "2-1", "ch": 2, "n": 1, "stem": "In un'ampia coorte di adulti con meningite batterica comunitaria, la triade classica di febbre, rigidità nucale e alterazione dello stato di coscienza era presente in circa:", "opts": ["Il 95% dei pazienti", "Il 44% dei pazienti", "Il 10% dei pazienti", "L'80% dei pazienti"], "a": 1, "sec": ["4.1"]}, {"id": "2-2", "ch": 2, "n": 2, "stem": "La causa più frequente di meningite batterica comunitaria dell'adulto in Europa è:", "opts": ["<em>Neisseria meningitidis</em>", "<em>Listeria monocytogenes</em>", "<em>Haemophilus influenzae</em> tipo b", "<em>Streptococcus pneumoniae</em>"], "a": 3, "sec": ["1.1", "2"]}, {"id": "2-3", "ch": 2, "n": 3, "stem": "Un uomo di 68 anni si presenta con febbre, cefalea e confusione. Lo schema empirico più appropriato, in un contesto con pneumococchi resistenti alle cefalosporine, è:", "opts": ["Ceftriaxone + vancomicina + amoxicillina", "Solo ceftriaxone", "Ceftriaxone + azitromicina", "Vancomicina + ciprofloxacina"], "a": 0, "sec": ["6.1"]}, {"id": "2-4", "ch": 2, "n": 4, "stem": "L'amoxicillina/ampicillina si aggiunge alla terapia empirica nei pazienti con più di 50 anni perché:", "opts": ["Copre gli pneumococchi resistenti alla penicillina", "Copre <em>S. aureus</em> resistente alla meticillina", "<em>Listeria monocytogenes</em> è intrinsecamente resistente alle cefalosporine", "Copre gli anaerobi provenienti dai seni paranasali"], "a": 2, "sec": ["6.1"]}, {"id": "2-5", "ch": 2, "n": 5, "stem": "Secondo le linee guida attuali, quale reperto è un'indicazione all'imaging cerebrale prima della rachicentesi?", "opts": ["La sola età superiore a 60 anni", "Febbre con rigidità nucale", "Una paralisi isolata del sesto nervo cranico", "Crisi epilettiche di nuova insorgenza"], "a": 3, "sec": ["5.2"]}, {"id": "2-6", "ch": 2, "n": 6, "stem": "Un paziente con sospetta meningite batterica necessita di una TC prima della rachicentesi. La sequenza corretta è:", "opts": ["TC, poi rachicentesi, poi antibiotici", "Emocolture, desametasone e antibiotici, poi TC, poi rachicentesi", "Prima la rachicentesi, poi gli antibiotici dopo la colorazione di Gram", "Antibiotici orali in attesa della TC"], "a": 1, "sec": ["5.2"]}, {"id": "2-7", "ch": 2, "n": 7, "stem": "Il liquor mostra 2.500 globuli bianchi/µl (90% neutrofili), rapporto glucosio liquor/sangue 0,2 e proteine 3 g/l. La diagnosi più probabile è:", "opts": ["Meningite virale", "Liquor normale", "Meningite batterica", "Meningite criptococcica"], "a": 2, "sec": ["5.3"]}, {"id": "2-8", "ch": 2, "n": 8, "stem": "Un paziente ha da 3 settimane cefalea e febbre, paralisi del sesto nervo cranico, iponatriemia, liquor linfocitario con glucosio molto basso e proteine 2,5 g/l, e alla RM potenziamento meningeo basale con idrocefalo. La diagnosi più probabile è:", "opts": ["Meningite tubercolare", "Meningite da enterovirus", "Meningite meningococcica", "Meningite da HSV-2"], "a": 0, "sec": ["4.4", "5.3", "5.4"]}, {"id": "2-9", "ch": 2, "n": 9, "stem": "Riguardo al desametasone aggiuntivo nella meningite batterica dell'adulto:", "opts": ["Va iniziato solo dopo una coltura del liquor positiva", "Va iniziato prima o insieme alla prima dose di antibiotico, per 4 giorni, con il beneficio maggiore nella meningite pneumococcica", "È raccomandato nei neonati", "È raccomandato nella meningite criptococcica"], "a": 1, "sec": ["6.2"]}, {"id": "2-10", "ch": 2, "n": 10, "stem": "Un paziente con infezione da HIV avanzata (CD4 40/µl) ha da 3 settimane una cefalea in lento peggioramento, con lieve rigidità nucale. Quale esame su liquor e siero conferma meglio la diagnosi più probabile?", "opts": ["Colorazione di Gram e coltura batterica", "PCR per enterovirus", "Antigene criptococcico (CrAg)", "Titolo antistreptolisinico (TAS)"], "a": 2, "sec": ["1.2", "5.4"]}, {"id": "2-11", "ch": 2, "n": 11, "stem": "La durata raccomandata del trattamento della meningite meningococcica non complicata è:", "opts": ["21 giorni", "14 giorni", "3 giorni", "7 giorni"], "a": 3, "sec": ["6.3"]}, {"id": "2-12", "ch": 2, "n": 12, "stem": "La durata raccomandata del trattamento della meningite da <em>Listeria</em> è:", "opts": ["Almeno 21 giorni", "5 giorni", "7 giorni", "10 giorni"], "a": 0, "sec": ["6.3"]}, {"id": "2-13", "ch": 2, "n": 13, "stem": "Quale farmaco si usa per la chemioprofilassi dei contatti stretti di un paziente con meningite meningococcica?", "opts": ["Amoxicillina", "Doxiciclina", "Ciprofloxacina", "Vancomicina"], "a": 2, "sec": ["8.2"]}, {"id": "2-14", "ch": 2, "n": 14, "stem": "Un uomo ha il terzo episodio di meningite pneumococcica, due anni dopo un trauma cranico. La condizione predisponente più probabile è:", "opts": ["Una fistola liquorale da frattura della base cranica", "Un deficit dei componenti terminali del complemento (C5–C9)", "Un'infezione ricorrente da HSV-2", "Un'infezione da virus Toscana"], "a": 0, "sec": ["3", "7.2"]}, {"id": "2-15", "ch": 2, "n": 15, "stem": "La malattia meningococcica invasiva ricorrente è classicamente associata a:", "opts": ["Deficit selettivo di IgA", "Malattia granulomatosa cronica", "Sindrome di DiGeorge", "Deficit dei componenti terminali del complemento o terapia con inibitori del complemento"], "a": 3, "sec": ["2", "7.2"]}, {"id": "2-16", "ch": 2, "n": 16, "stem": "La causa più frequente di meningite virale è:", "opts": ["HSV-1", "Enterovirus", "Citomegalovirus", "Virus di Epstein-Barr"], "a": 1, "sec": ["1.2"]}, {"id": "2-17", "ch": 2, "n": 17, "stem": "In estate, un paziente dell'Italia centrale sviluppa una meningite linfocitaria dopo punture di flebotomi. La causa più probabile è:", "opts": ["Virus Toscana", "Virus West Nile", "Virus dell'encefalite da zecche", "Virus della coriomeningite linfocitaria"], "a": 0, "sec": ["1.2"]}, {"id": "2-18", "ch": 2, "n": 18, "stem": "Dopo una meningite pneumococcica, quale passo del follow-up è più importante?", "opts": ["Una rachicentesi di routine a fine trattamento", "Una RM cerebrale di routine a 6 mesi", "Una valutazione precoce dell'udito, idealmente prima della dimissione", "Un EEG in tutti i pazienti"], "a": 2, "sec": ["7.2"]}, {"id": "2-19", "ch": 2, "n": 19, "stem": "Una rachicentesi di controllo durante il trattamento della meningite batterica è indicata quando:", "opts": ["Ogni paziente completa la terapia", "La causa è il meningococco", "Mai, perché non fornisce informazioni", "Non c'è miglioramento clinico entro 48 ore da una terapia appropriata"], "a": 3, "sec": ["7.1"]}, {"id": "2-20", "ch": 2, "n": 20, "stem": "Quale vaccino è stato sviluppato per la cintura africana della meningite e copre il sierogruppo X?", "opts": ["MenB (proteico)", "Men5CV (A, C, W, Y, X)", "PCV20", "Coniugato anti-Hib"], "a": 1, "sec": ["8.1"]}, {"id": "3-1", "ch": 3, "n": 1, "stem": "Nei Paesi ad alto reddito la causa più frequente di endocardite infettiva è:", "opts": ["Gli streptococchi viridanti del cavo orale", "<em>Staphylococcus aureus</em>", "<em>Enterococcus faecalis</em>", "Gli stafilococchi coagulasi-negativi"], "a": 1, "sec": ["1"]}, {"id": "3-2", "ch": 3, "n": 2, "stem": "Un uomo di 72 anni ha un'EI da <em>Streptococcus gallolyticus</em>. Quale ulteriore accertamento è più importante?", "opts": ["Ecocolordoppler venoso degli arti superiori", "Solo l'ortopantomografia", "Biopsia osteomidollare", "Colonscopia"], "a": 3, "sec": ["1"]}, {"id": "3-3", "ch": 3, "n": 3, "stem": "Nelle persone che si iniettano droghe la valvola più tipicamente coinvolta nell'EI è:", "opts": ["La tricuspide", "La mitrale", "L'aortica", "La polmonare"], "a": 0, "sec": ["2.1"]}, {"id": "3-4", "ch": 3, "n": 4, "stem": "I noduli di Osler sono descritti meglio come:", "opts": ["Macule emorragiche indolori su palmi e piante", "Emorragie retiniche con centro pallido", "Noduli dolorosi sui polpastrelli delle dita delle mani e dei piedi, di origine immunologica", "Strie lineari scure sotto le unghie"], "a": 2, "sec": ["4"]}, {"id": "3-5", "ch": 3, "n": 5, "stem": "Nel sospetto di EI in un paziente emodinamicamente stabile, le emocolture vanno prelevate come segue:", "opts": ["Almeno tre set prima di iniziare gli antibiotici", "Un set dopo la prima dose di antibiotico", "Solo se la temperatura supera i 39 °C", "Solo da un catetere arterioso"], "a": 0, "sec": ["5.2"]}, {"id": "3-6", "ch": 3, "n": 6, "stem": "Secondo gli attuali criteri di Duke, un'EI certa su base clinica richiede:", "opts": ["1 criterio maggiore + 1 minore", "2 maggiori, oppure 1 maggiore + 3 minori, oppure 5 minori", "3 criteri minori", "1 solo criterio maggiore"], "a": 1, "sec": ["5.5"]}, {"id": "3-7", "ch": 3, "n": 7, "stem": "Quale dei seguenti è un criterio maggiore negli attuali criteri di Duke?", "opts": ["Febbre &gt;38,0 °C", "Fattore reumatoide positivo", "Emorragie a scheggia", "Evidenza di EI all'ispezione diretta durante un intervento cardiochirurgico"], "a": 3, "sec": ["5.5"]}, {"id": "3-8", "ch": 3, "n": 8, "stem": "L'esame di imaging di prima linea nel sospetto di EI è:", "opts": ["La RM cardiaca", "La PET/TC con FDG", "L'ecocardiogramma transtoracico", "La coronarografia"], "a": 2, "sec": ["5.3"]}, {"id": "3-9", "ch": 3, "n": 9, "stem": "Un paziente con protesi valvolare aortica meccanica ha una batteriemia da <em>S. aureus</em>; l'ETE è negativo ma il sospetto resta alto. Il passo successivo migliore è:", "opts": ["Escludere l'EI e sospendere gli accertamenti", "Sospendere gli antibiotici e ripetere le emocolture dopo 1 mese", "Ripetere l'ETE dopo 5–7 giorni e/o eseguire TC cardiaca o PET/TC con FDG", "Eseguire un cateterismo cardiaco"], "a": 2, "sec": ["5.3"]}, {"id": "3-10", "ch": 3, "n": 10, "stem": "La causa più frequente di EI a emocolture negative è:", "opts": ["La terapia antibiotica somministrata prima delle emocolture", "<em>Staphylococcus aureus</em>", "<em>Escherichia coli</em>", "<em>Candida albicans</em>"], "a": 0, "sec": ["5.4"]}, {"id": "3-11", "ch": 3, "n": 11, "stem": "Quale reperto è un criterio microbiologico maggiore per l'EI da <em>Coxiella burnetii</em>?", "opts": ["IgM di fase II ≥1:50", "Una singola emocoltura positiva", "Fattore reumatoide positivo", "Titolo di IgG di fase I &gt;1:800"], "a": 3, "sec": ["5.4", "5.5"]}, {"id": "3-12", "ch": 3, "n": 12, "stem": "Nell'EI su valvola nativa da <em>Staphylococcus aureus</em>, quale affermazione sulla terapia è corretta?", "opts": ["La vancomicina è la prima scelta sia per MSSA sia per MRSA", "MSSA si tratta con una penicillina antistafilococcica o con la cefazolina; MRSA con vancomicina o daptomicina", "La gentamicina va aggiunta di routine per MSSA", "MRSA si tratta con cefazolina ad alte dosi"], "a": 1, "sec": ["6.3"]}, {"id": "3-13", "ch": 3, "n": 13, "stem": "Nell'EI con emocolture inizialmente positive, la durata della terapia antibiotica si conta a partire:", "opts": ["Dal giorno del ricovero", "Dal primo giorno di emocolture negative in terapia efficace", "Dal giorno del primo ecocardiogramma", "Dal giorno della scomparsa della febbre"], "a": 1, "sec": ["6.1"]}, {"id": "3-14", "ch": 3, "n": 14, "stem": "Nei pazienti stabili con EI sinistra che rispondono alla terapia endovenosa iniziale:", "opts": ["Il passaggio agli antibiotici orali dopo almeno 10 giorni di terapia e.v. è efficace quanto proseguire la terapia e.v.", "La terapia orale dal primo giorno è superiore a quella e.v.", "Due settimane di terapia bastano per tutti i microrganismi", "La chirurgia non è mai necessaria"], "a": 0, "sec": ["6.4"]}, {"id": "3-15", "ch": 3, "n": 15, "stem": "Quale situazione è un'indicazione alla chirurgia in emergenza (entro 24 ore)?", "opts": ["Una vegetazione mitralica di 6 mm senza complicanze", "Febbre che dura 3 giorni dopo l'inizio degli antibiotici", "Insufficienza aortica acuta grave con edema polmonare refrattario", "Microematuria"], "a": 2, "sec": ["6.5"]}, {"id": "3-16", "ch": 3, "n": 16, "stem": "Un paziente portatore di pacemaker ha un'EI correlata al dispositivo. La gestione corretta è:", "opts": ["Solo antibiotici per 2 settimane", "Rimozione del solo generatore, lasciando gli elettrocateteri", "Terapia antifungina", "Rimozione completa del dispositivo e di tutti gli elettrocateteri, più antibiotici"], "a": 3, "sec": ["6.5"]}, {"id": "3-17", "ch": 3, "n": 17, "stem": "Secondo le linee guida attuali, quale paziente è ad alto rischio e deve ricevere la profilassi antibiotica prima di una procedura odontoiatrica ad alto rischio?", "opts": ["Un paziente con EI pregressa", "Un paziente con difetto interatriale isolato mai corretto", "Un paziente con bypass aortocoronarici", "Un paziente iperteso"], "a": 0, "sec": ["8.2"]}, {"id": "3-18", "ch": 3, "n": 18, "stem": "In un paziente ad alto rischio la profilassi antibiotica è raccomandata prima di:", "opts": ["Broncoscopia senza biopsia", "Colonscopia", "Estrazione dentaria", "Iniezione di anestetico locale in tessuto non infetto"], "a": 2, "sec": ["8.2"]}, {"id": "3-19", "ch": 3, "n": 19, "stem": "Quale dei seguenti antibiotici non è un'opzione per la profilassi dell'EI nei pazienti allergici alla penicillina?", "opts": ["Azitromicina", "Claritromicina", "Doxiciclina", "Piperacillina/tazobactam"], "a": 3, "sec": ["8.2"]}, {"id": "3-20", "ch": 3, "n": 20, "stem": "Nell'EI su valvola nativa da <em>S. aureus</em> sensibile alla meticillina, l'aggiunta della gentamicina è:", "opts": ["Obbligatoria per 6 settimane", "Non raccomandata, per nefrotossicità senza beneficio clinico", "Raccomandata solo nei pazienti giovani", "La monoterapia preferita"], "a": 1, "sec": ["6.3"]}, {"id": "4-1", "ch": 4, "n": 1, "stem": "La diagnosi di CAP richiede in genere:", "opts": ["La sola febbre", "La sola leucocitosi", "Un'opacità all'imaging del torace associata a una sindrome clinica compatibile", "Un'emocoltura positiva"], "a": 2, "sec": ["5.1"]}, {"id": "4-2", "ch": 4, "n": 2, "stem": "Se il sospetto di CAP è elevato ma la radiografia del torace è negativa, un passo successivo ragionevole è:", "opts": ["La TC del torace in casi selezionati", "Nessun ulteriore imaging", "La RM del torace", "La PET"], "a": 0, "sec": ["5.1"]}, {"id": "4-3", "ch": 4, "n": 3, "stem": "Lo score di gravità preferito per integrare il giudizio clinico nelle decisioni sul setting di cura della CAP è:", "opts": ["Lo score di Wells", "Il qSOFA", "Il CHA2DS2-VASc", "Il Pneumonia Severity Index (PSI)"], "a": 3, "sec": ["5.2"]}, {"id": "4-4", "ch": 4, "n": 4, "stem": "I pazienti in classe PSI IV–V in genere devono:", "opts": ["Essere sempre dimessi a domicilio", "Essere ricoverati in ospedale, valutando la terapia intensiva", "Non ricevere antibiotici", "Essere trattati solo con antivirali"], "a": 1, "sec": ["5.2"]}, {"id": "4-5", "ch": 4, "n": 5, "stem": "Negli adulti senza malattia polmonare di base, una saturazione di ossigeno in aria ambiente &lt;92% di nuova insorgenza suggerisce che:", "opts": ["L'osservazione con rivalutazione o il ricovero sono più sicuri che attendere valori &lt;90%", "La gestione ambulatoriale senza rivalutazione è sicura", "Non ha significato clinico", "Il ricovero in terapia intensiva è obbligatorio"], "a": 0, "sec": ["5.2"]}, {"id": "4-6", "ch": 4, "n": 6, "stem": "I criteri maggiori per la terapia intensiva nella CAP grave comprendono:", "opts": ["Febbre e tosse", "Qualsiasi leucocitosi", "Necessità di ventilazione meccanica o shock settico che richiede vasopressori", "Qualsiasi versamento pleurico"], "a": 2, "sec": ["5.2"]}, {"id": "4-7", "ch": 4, "n": 7, "stem": "Nella maggior parte dei pazienti ambulatoriali con CAP lieve, le indagini microbiologiche sono:", "opts": ["Sempre necessarie (emocolture ed esame colturale dell'espettorato)", "Necessarie per scegliere gli antibiotici", "Necessarie per diagnosticare la CAP", "In genere non necessarie, salvo test virali selezionati quando modificano la gestione"], "a": 3, "sec": ["5.3"]}, {"id": "4-8", "ch": 4, "n": 8, "stem": "Nella maggior parte dei pazienti ricoverati in reparto con CAP moderata, le indagini tipiche comprendono:", "opts": ["La coprocoltura", "Emocolture, colorazione di Gram/coltura dell'espettorato, antigene urinario pneumococcico, test per <em>Legionella</em> e test virali nella stagione epidemica", "La biopsia cutanea", "Solo l'ecocardiografia"], "a": 1, "sec": ["5.3"]}, {"id": "4-9", "ch": 4, "n": 9, "stem": "La PCR/coltura nasale per MRSA si esegue in particolare in presenza di:", "opts": ["CAP lieve ambulatoriale", "Richiesta del paziente", "Fattori di rischio per MRSA, malattia grave o malattia virale bifasica seguita da peggioramento", "Sospetto di <em>Legionella</em>"], "a": 2, "sec": ["5.3"]}, {"id": "4-10", "ch": 4, "n": 10, "stem": "Nella CAP grave, i campioni broncoscopici si considerano:", "opts": ["Quando fattibile, bilanciando il beneficio diagnostico rispetto ai rischi procedurali", "Mai", "Solo nei pazienti ambulatoriali", "Solo dopo la dimissione"], "a": 0, "sec": ["5.3"]}, {"id": "4-11", "ch": 4, "n": 11, "stem": "La polmonite cavitaria può richiedere la ricerca di:", "opts": ["Appendicite", "Otite media", "Cistite", "Tubercolosi, patogeni fungini e <em>Nocardia</em>"], "a": 3, "sec": ["5.4"]}, {"id": "4-12", "ch": 4, "n": 12, "stem": "I regimi empirici ambulatoriali per la CAP sono concepiti per coprire:", "opts": ["Solo virus", "<em>S. pneumoniae</em>, <em>H. influenzae</em> e patogeni atipici", "Solo MRSA", "Solo <em>Pseudomonas</em>"], "a": 1, "sec": ["6.1"]}, {"id": "4-13", "ch": 4, "n": 13, "stem": "I pazienti ambulatoriali che più probabilmente necessitano di una copertura ampliata per gram-negativi/MSSA comprendono:", "opts": ["Anziani, fumatori e pazienti con comorbidità o uso recente di antibiotici", "Giovani adulti sani senza comorbidità", "Pazienti con faringodinia isolata", "Pazienti con allergie stagionali"], "a": 0, "sec": ["6.1"]}, {"id": "4-14", "ch": 4, "n": 14, "stem": "La CAP in terapia intensiva ha maggiori probabilità di coinvolgere:", "opts": ["Solo patogeni atipici", "Solo anaerobi", "Patogeni resistenti, incluso CA-MRSA, e <em>Legionella</em>", "Solo funghi"], "a": 2, "sec": ["6.2"]}, {"id": "4-15", "ch": 4, "n": 15, "stem": "I fattori di rischio più forti per MRSA nella CAP comprendono:", "opts": ["Solo un viaggio recente", "Solo una tosse lieve", "Una radiografia del torace normale", "Colonizzazione nota da MRSA, infezione pregressa da MRSA o cocchi gram-positivi a grappolo alla colorazione di Gram dell'espettorato"], "a": 3, "sec": ["6.3"]}, {"id": "4-16", "ch": 4, "n": 16, "stem": "Quale caratteristica aumenta il sospetto di polmonite da MRSA nella CAP grave?", "opts": ["Solo rinorrea", "Polmonite necrotizzante o cavitaria", "Dolore pleuritico isolato con imaging normale", "Bradicardia"], "a": 1, "sec": ["6.3"]}, {"id": "4-17", "ch": 4, "n": 17, "stem": "La maggior parte dei pazienti con CAP dovrebbe mostrare un certo miglioramento entro:", "opts": ["6 ore", "2-3 settimane", "48-72 ore", "2-3 mesi"], "a": 2, "sec": ["7.1"]}, {"id": "4-18", "ch": 4, "n": 18, "stem": "La mancata risposta entro 48-72 ore suggerisce:", "opts": ["In tutti i casi solo una polmonite virale", "Che gli antibiotici vanno sempre sospesi immediatamente", "Che non è necessaria alcuna ulteriore valutazione", "Un patogeno resistente, una complicanza o una diagnosi errata"], "a": 3, "sec": ["7.1"]}, {"id": "4-19", "ch": 4, "n": 19, "stem": "Una radiografia del torace di controllo di routine dopo la risoluzione clinica è:", "opts": ["In genere non necessaria; la risposta radiologica è in ritardo rispetto a quella clinica", "Sempre necessaria", "Necessaria entro 24 ore", "Necessaria in tutti i pazienti sotto i 30 anni"], "a": 0, "sec": ["7.2"]}, {"id": "4-20", "ch": 4, "n": 20, "stem": "I vaccini che riducono il rischio di CAP negli adulti comprendono:", "opts": ["Il vaccino antirabbico", "I vaccini contro influenza, COVID-19, pneumococco e RSV (in base a età/rischio)", "Solo il vaccino contro la febbre gialla", "Solo il vaccino antitifico"], "a": 1, "sec": ["8"]}, {"id": "5-1", "ch": 5, "n": 1, "stem": "La HAP è definita come una polmonite che insorge:", "opts": ["≥48 ore dopo il ricovero e non in incubazione al momento del ricovero", "Entro 24 ore dal ricovero", "Solo nei pazienti ventilati", "Solo dopo la dimissione"], "a": 0, "sec": ["2.1"]}, {"id": "5-2", "ch": 5, "n": 2, "stem": "La VAP è definita come una polmonite che si sviluppa in un paziente intubato in ventilazione meccanica da:", "opts": ["≥12 ore", "≥24 ore", "<blockquote>\n<p>48 ore</p>\n</blockquote>", "Solo &gt;7 giorni"], "a": 2, "sec": ["2.1"]}, {"id": "5-3", "ch": 5, "n": 3, "stem": "La VAP comprende anche la HAP che insorge entro:", "opts": ["6 ore dall'estubazione", "24 ore dall'estubazione", "7 giorni dall'estubazione", "48 ore dall'estubazione"], "a": 3, "sec": ["2.1"]}, {"id": "5-4", "ch": 5, "n": 4, "stem": "La principale via di infezione in HAP/VAP è:", "opts": ["La diffusione ematogena dalla cute", "La microaspirazione di microrganismi che colonizzano l'orofaringe", "Il morso di zecca", "La trasmissione sessuale"], "a": 1, "sec": ["3"]}, {"id": "5-5", "ch": 5, "n": 5, "stem": "I patogeni più comuni di HAP/VAP comprendono:", "opts": ["<em>S. aureus</em> (incluso MRSA) e <em>P. aeruginosa</em>", "Solo anaerobi", "Solo <em>S. pneumoniae</em>", "Solo funghi"], "a": 0, "sec": ["1"]}, {"id": "5-6", "ch": 5, "n": 6, "stem": "I principali fattori di rischio per MDR comprendono:", "opts": ["Nessun antibiotico mai assunto in precedenza", "Età &lt;30 anni", "Allergie stagionali", "Colonizzazione nota da MDR, ricovero ≥5 giorni e/o antibiotici nei 90 giorni precedenti"], "a": 3, "sec": ["2.2"]}, {"id": "5-7", "ch": 5, "n": 7, "stem": "La diagnosi clinica di HAP/VAP si basa su:", "opts": ["La sola emocoltura positiva", "La sola procalcitonina", "Un nuovo infiltrato più febbre/secrezioni purulente/leucocitosi e peggioramento dell'ossigenazione", "Solo la TC"], "a": 2, "sec": ["5.1"]}, {"id": "5-8", "ch": 5, "n": 8, "stem": "La VAP non può essere confermata o esclusa finché:", "opts": ["Non viene somministrata la prima dose di antibiotico", "I risultati colturali non sono completi (spesso 2-3 giorni)", "Il ventilatore non viene rimosso", "La radiografia del torace non è normale"], "a": 1, "sec": ["5.2"]}, {"id": "5-9", "ch": 5, "n": 9, "stem": "Una coltura respiratoria positiva con una radiografia del torace normale suggerisce:", "opts": ["Tracheobronchite", "Embolia polmonare", "Pneumotorace", "Scompenso cardiaco"], "a": 0, "sec": ["5.2"]}, {"id": "5-10", "ch": 5, "n": 10, "stem": "La soglia colturale quantitativa tipica a supporto della VAP per un aspirato endotracheale è:", "opts": ["10 UFC/ml", "1.000 UFC/ml", "10.000 UFC/ml", "≥1.000.000 UFC/ml"], "a": 3, "sec": ["5.3"]}, {"id": "5-11", "ch": 5, "n": 11, "stem": "La soglia colturale quantitativa tipica a supporto della VAP per BAL/mini-BAL è:", "opts": ["100 UFC/ml", "1.000 UFC/ml", "10.000 UFC/ml", "1.000.000 UFC/ml"], "a": 2, "sec": ["5.3"]}, {"id": "5-12", "ch": 5, "n": 12, "stem": "La soglia colturale quantitativa tipica a supporto della VAP per lo spazzolato protetto è:", "opts": ["10 UFC/ml", "1.000 UFC/ml", "10.000 UFC/ml", "1.000.000 UFC/ml"], "a": 1, "sec": ["5.3"]}, {"id": "5-13", "ch": 5, "n": 13, "stem": "La scelta della terapia empirica deve tenere conto di:", "opts": ["Colture precedenti, antibiotici recenti, resistenze locali, gravità, colorazione di Gram e fattori di rischio per MDR", "Solo l'età del paziente", "Solo il quadro radiologico del torace", "Solo la procalcitonina"], "a": 0, "sec": ["6.1"]}, {"id": "5-14", "ch": 5, "n": 14, "stem": "La HAP/VAP grave comprende:", "opts": ["Qualsiasi febbre", "Solo una lieve leucocitosi", "Ossigenazione normale", "Shock settico di nuova insorgenza (VAP/NV-HAP) e/o nuova necessità di supporto ventilatorio (NV-HAP)"], "a": 3, "sec": ["6.2"]}, {"id": "5-15", "ch": 5, "n": 15, "stem": "La rivalutazione ai fini della de-escalation deve avvenire entro:", "opts": ["6 ore", "12 ore", "48-72 ore", "24 ore"], "a": 2, "sec": ["7.1"]}, {"id": "5-16", "ch": 5, "n": 16, "stem": "Se la PCR/coltura nasale per MRSA è negativa, l'azione suggerita è:", "opts": ["Proseguire la terapia anti-MRSA per 14 giorni", "Sospendere la terapia empirica anti-MRSA per ridurre l'uso non necessario di antibiotici", "Aggiungere un secondo farmaco anti-MRSA", "Passare a una terapia antifungina"], "a": 1, "sec": ["7.2"]}, {"id": "5-17", "ch": 5, "n": 17, "stem": "La durata raccomandata della terapia nella maggior parte delle HAP/VAP è:", "opts": ["7 giorni", "3 giorni", "5 giorni", "21 giorni"], "a": 0, "sec": ["6.4"]}, {"id": "5-18", "ch": 5, "n": 18, "stem": "Cicli più lunghi di 7 giorni possono essere giustificati in:", "opts": ["Tutti i pazienti", "Pazienti selezionati, come quelli con empiema, ascesso polmonare, risposta lenta, immunocompromissione o batteriemia da <em>S. aureus</em>", "Solo quelli con colture normali", "Solo quelli con polmonite virale"], "a": 1, "sec": ["6.4"]}, {"id": "5-19", "ch": 5, "n": 19, "stem": "Il passaggio alla terapia orale è in genere appropriato quando il paziente è:", "opts": ["Ancora in shock", "Ancora in peggioramento dell'ossigenazione", "Emodinamicamente stabile, in miglioramento clinico e in grado di tollerare farmaci per via orale", "Incapace di deglutire"], "a": 2, "sec": ["6.4"]}, {"id": "5-20", "ch": 5, "n": 20, "stem": "Quale delle seguenti è una pratica di prevenzione essenziale per VAP/NV-HAP?", "opts": ["L'igiene orale di routine con clorexidina", "Il cambio quotidiano dei circuiti del ventilatore", "Evitare i protocolli di svezzamento dal ventilatore", "Il sollevamento della testata del letto e l'igiene orale con spazzolamento dei denti (senza clorexidina)"], "a": 3, "sec": ["8"]}, {"id": "6-1", "ch": 6, "n": 1, "stem": "Quale meccanismo permette a un nuovo sottotipo di virus influenzale A di emergere e causare una pandemia?", "opts": ["La deriva antigenica dovuta a mutazioni puntiformi dell'emoagglutinina", "Mutazioni puntiformi della neuraminidasi che causano resistenza a oseltamivir", "Lo spostamento antigenico dovuto al riassortimento di segmenti genomici tra diversi virus influenzali A", "La ricombinazione tra virus influenzali A e B"], "a": 2, "sec": ["1.2"]}, {"id": "6-2", "ch": 6, "n": 2, "stem": "SARS-CoV-2 entra nelle cellule respiratorie umane principalmente tramite il legame della proteina spike a:", "opts": ["Enzima di conversione dell'angiotensina 2 (ACE2), dopo attivazione da parte di TMPRSS2", "Acido sialico con legame α2,6", "CD4 e il corecettore CCR5", "Molecola di adesione intercellulare 1 (ICAM-1)"], "a": 0, "sec": ["1.3", "3.2"]}, {"id": "6-3", "ch": 6, "n": 3, "stem": "Quale dei seguenti gruppi è a più alto rischio di malattia grave da RSV?", "opts": ["Bambini sani in età scolare", "Adulti sani di 20-40 anni", "Adolescenti con asma lieve", "Lattanti sotto i 6 mesi (soprattutto prematuri) e adulti di 60 anni o più con malattie croniche cardiache o polmonari"], "a": 3, "sec": ["2.3"]}, {"id": "6-4", "ch": 6, "n": 4, "stem": "L'influenza aviaria A(H5N1) causa polmonite grave nell'uomo ma si trasmette poco da persona a persona principalmente perché:", "opts": ["Non è in grado di replicarsi alla temperatura corporea umana", "Lega preferenzialmente l'acido sialico con legame α2,3, presente soprattutto nelle basse vie respiratorie", "È priva della proteina neuraminidasi", "È completamente neutralizzata dagli anticorpi indotti dai vaccini stagionali"], "a": 1, "sec": ["3.1"]}, {"id": "6-5", "ch": 6, "n": 5, "stem": "Un uomo di 24 anni, precedentemente sano, ha avuto l'influenza una settimana fa. Dopo un miglioramento iniziale sviluppa febbre elevata, emottisi e shock settico. La TC del torace mostra multipli addensamenti escavati. Quale patogeno è la causa più probabile?", "opts": ["<em>Legionella pneumophila</em>", "<em>Staphylococcus aureus</em> (incluso MRSA comunitario)", "<em>Mycoplasma pneumoniae</em>", "<em>Pseudomonas aeruginosa</em>"], "a": 1, "sec": ["3.4", "4.2", "6.2"]}, {"id": "6-6", "ch": 6, "n": 6, "stem": "Quale dei seguenti definisce una COVID-19 <strong>grave</strong> nell'adulto?", "opts": ["Qualsiasi polmonite visibile alla TC del torace", "Febbre superiore a 39 °C per più di 3 giorni", "La necessità di ventilazione meccanica invasiva", "Saturazione di ossigeno inferiore al 90% in aria ambiente, frequenza respiratoria superiore a 30/min o segni di grave distress respiratorio"], "a": 3, "sec": ["4.3"]}, {"id": "6-7", "ch": 6, "n": 7, "stem": "La causa più frequente di bronchiolite nel lattante è:", "opts": ["Il virus respiratorio sinciziale", "Il virus influenzale B", "L'adenovirus", "<em>Bordetella pertussis</em>"], "a": 0, "sec": ["4.4"]}, {"id": "6-8", "ch": 6, "n": 8, "stem": "In un paziente ricoverato con sospetta influenza, il test diagnostico preferito è:", "opts": ["Un test antigenico rapido, perché un risultato negativo esclude l'influenza", "La coltura virale di un tampone nasofaringeo", "Un test molecolare (RT-PCR) su un campione respiratorio", "Un singolo campione di siero per la ricerca di anticorpi anti-influenzali"], "a": 2, "sec": ["5.2"]}, {"id": "6-9", "ch": 6, "n": 9, "stem": "Il reperto TC del torace più tipico nella polmonite da COVID-19 è:", "opts": ["Addensamento lobare con broncogramma aereo in un solo lobo", "Una cavità a parete spessa nel lobo superiore", "Opacità a vetro smerigliato bilaterali, periferiche e basali", "Un ampio versamento pleurico monolaterale"], "a": 2, "sec": ["5.3"]}, {"id": "6-10", "ch": 6, "n": 10, "stem": "Quale affermazione sui corticosteroidi nella polmonite influenzale è corretta?", "opts": ["Non sono raccomandati, salvo necessità per un altro motivo (es. riacutizzazione di BPCO, shock settico)", "Sono raccomandati in tutti i pazienti ricoverati che necessitano di ossigeno", "Devono sostituire la terapia antivirale quando i sintomi sono iniziati da più di 48 ore", "Riducono il rischio di aspergillosi polmonare associata a influenza"], "a": 0, "sec": ["6.2"]}, {"id": "6-11", "ch": 6, "n": 11, "stem": "Una donna di 70 anni viene ricoverata con febbre, tosse e ipossiemia durante la stagione influenzale. I sintomi sono iniziati 4 giorni fa. Il risultato della PCR per l'influenza sarà disponibile domani. Qual è la gestione migliore?", "opts": ["Nessun trattamento antivirale, perché sono trascorse più di 48 ore dall'esordio", "Attendere il risultato della PCR prima di iniziare qualsiasi antivirale", "Iniziare amantadina, attiva sia contro l'influenza A sia contro la B", "Iniziare subito oseltamivir, senza attendere il risultato del test"], "a": 3, "sec": ["6.2"]}, {"id": "6-12", "ch": 6, "n": 12, "stem": "Un uomo di 78 anni con diabete ha sintomi lievi di COVID-19 da 2 giorni. La saturazione di ossigeno è 96% in aria ambiente. Quale trattamento è più appropriato?", "opts": ["Desametasone", "Nirmatrelvir-ritonavir, dopo aver verificato le interazioni farmacologiche", "Tocilizumab", "Plasma da convalescenti"], "a": 1, "sec": ["6.3"]}, {"id": "6-13", "ch": 6, "n": 13, "stem": "Prima di prescrivere nirmatrelvir-ritonavir, la preoccupazione più importante è:", "opts": ["La tossicità renale", "Le interazioni farmaco-farmaco", "L'interazione con il cibo", "La resistenza virale"], "a": 1, "sec": ["6.3"]}, {"id": "6-14", "ch": 6, "n": 14, "stem": "Un paziente di 60 anni ricoverato per COVID-19 necessita di ossigeno ad alti flussi; la proteina C reattiva è in aumento. Il trattamento raccomandato comprende:", "opts": ["Desametasone più un inibitore del recettore dell'IL-6 (es. tocilizumab) o baricitinib", "Ivermectina più idrossiclorochina", "Molnupiravir più azitromicina", "Solo terapia di supporto, perché gli immunomodulatori sono dannosi"], "a": 0, "sec": ["6.3"]}, {"id": "6-15", "ch": 6, "n": 15, "stem": "Riguardo ai corticosteroidi sistemici in un paziente con COVID-19 non grave che non necessita di ossigeno:", "opts": ["Sono raccomandati in tutti i pazienti di età superiore a 65 anni", "Sono raccomandati se la proteina C reattiva è aumentata", "Sono raccomandati per prevenire la condizione post-COVID-19", "Non sono raccomandati, perché possono essere dannosi"], "a": 3, "sec": ["6.3"]}, {"id": "6-16", "ch": 6, "n": 16, "stem": "Un paziente in terapia intensiva con influenza grave, in ventilazione meccanica e in terapia con corticosteroidi, peggiora in sesta giornata. Il galattomannano su BAL è fortemente positivo. La diagnosi più probabile è:", "opts": ["Polmonite da <em>Pneumocystis jirovecii</em>", "Polmonite da citomegalovirus", "Aspergillosi polmonare associata a influenza", "Polmonite da <em>Legionella</em>"], "a": 2, "sec": ["3.4", "5.3"]}, {"id": "6-17", "ch": 6, "n": 17, "stem": "La condizione post-COVID-19 si diagnostica quando i sintomi:", "opts": ["Iniziano di solito entro 3 mesi dall'infezione, durano almeno 2 mesi e non possono essere spiegati da un'altra diagnosi", "Persistono per almeno 2 settimane dopo una PCR positiva", "Si verificano solo dopo una malattia grave che ha richiesto il ricovero in terapia intensiva", "Sono accompagnati da una PCR per SARS-CoV-2 persistentemente positiva"], "a": 0, "sec": ["7.2"]}, {"id": "6-18", "ch": 6, "n": 18, "stem": "Una donna al primo trimestre di gravidanza chiede informazioni sulla vaccinazione antinfluenzale all'inizio della stagione influenzale. Qual è il consiglio corretto?", "opts": ["Rimandare la vaccinazione a dopo il parto", "Vaccinare solo nel terzo trimestre", "La vaccinazione antinfluenzale è controindicata in gravidanza", "Offrire subito un vaccino antinfluenzale inattivato: è raccomandato in qualsiasi trimestre"], "a": 3, "sec": ["8.2"]}, {"id": "6-19", "ch": 6, "n": 19, "stem": "Nell'Unione Europea, il vaccino materno anti-RSV (Abrysvo) si somministra in gravidanza a:", "opts": ["8-12 settimane di gestazione", "14-20 settimane di gestazione", "24-36 settimane di gestazione", "Dopo il parto, durante l'allattamento"], "a": 2, "sec": ["8.6"]}, {"id": "6-20", "ch": 6, "n": 20, "stem": "Come si possono proteggere i neonati dalla malattia grave da RSV durante la loro prima stagione RSV?", "opts": ["Con un vaccino anti-RSV vivo attenuato somministrato alla nascita", "Con l'immunizzazione passiva: vaccinazione materna in gravidanza o un anticorpo monoclonale a lunga durata d'azione somministrato al lattante", "Con la profilassi con oseltamivir per tutta la stagione", "Non è disponibile alcuna misura preventiva per i lattanti"], "a": 1, "sec": ["8.6"]}, {"id": "7-1", "ch": 7, "n": 1, "stem": "La TB si trasmette più comunemente tramite:", "opts": ["Inalazione di goccioline di aerosol da TB polmonare/delle vie aeree", "Via oro-fecale", "Trasmissione sessuale", "Morso di zecca"], "a": 0, "sec": ["2"]}, {"id": "7-2", "ch": 7, "n": 2, "stem": "L'infezione tubercolare (TB latente) è meglio definita come:", "opts": ["Coltura dell'espettorato positiva con sintomi", "Malattia cavitaria alla radiografia del torace", "TST/IGRA positivo senza segni né sintomi di malattia", "Emottisi con febbre"], "a": 2, "sec": ["3.1"]}, {"id": "7-3", "ch": 7, "n": 3, "stem": "Il rischio di TB da riattivazione nel corso della vita nei soggetti immunocompetenti è approssimativamente:", "opts": ["&lt;1%", "1-2%", "5-10%", "<blockquote>\n<p>50%</p>\n</blockquote>"], "a": 2, "sec": ["3.1"]}, {"id": "7-4", "ch": 7, "n": 4, "stem": "La TB da riattivazione interessa più spesso:", "opts": ["Solo i lobi inferiori", "Solo la pleura", "Solo la trachea", "I segmenti apicali e posteriori dei lobi superiori"], "a": 3, "sec": ["4.1"]}, {"id": "7-5", "ch": 7, "n": 5, "stem": "I sintomi tipici della TB da riattivazione comprendono:", "opts": ["Diarrea acquosa acuta", "Tosse, calo ponderale, febbre, sudorazioni notturne e/o emottisi", "Solo un improvviso gonfiore unilaterale della gamba", "Disuria isolata"], "a": 1, "sec": ["4.1"]}, {"id": "7-6", "ch": 7, "n": 6, "stem": "Si deve sospettare una TB polmonare in presenza di sintomi compatibili più:", "opts": ["Rischio epidemiologico come esposizione o residenza/viaggi in aree endemiche", "Recente consumo di frutti di mare", "Solo una vaccinazione recente", "Allergie stagionali"], "a": 0, "sec": ["5.1"]}, {"id": "7-7", "ch": 7, "n": 7, "stem": "La diagnosi definitiva di TB polmonare è stabilita da:", "opts": ["Il solo IGRA positivo", "La sola radiografia del torace", "La leucocitosi", "L'isolamento di <em>M. tuberculosis</em> da una secrezione/un liquido biologico o da tessuto"], "a": 3, "sec": ["5.2"]}, {"id": "7-8", "ch": 7, "n": 8, "stem": "Nella maggior parte dei casi, un NAAT positivo in un paziente a rischio e non trattato è considerato:", "opts": ["Insufficiente per la diagnosi", "La prova di un micobatterio non tubercolare", "Sufficiente per la diagnosi di TB (con o senza positività dell'esame microscopico)", "Solo un test di screening per la TB latente"], "a": 2, "sec": ["5.2"]}, {"id": "7-9", "ch": 7, "n": 9, "stem": "Se l'imaging suggerisce una TB polmonare, la strategia raccomandata per l'espettorato è:", "opts": ["Un solo campione di espettorato", "Tre campioni di espettorato a ≥8 ore di distanza, di cui ≥1 al mattino presto, per esame microscopico/coltura/NAAT", "Due campioni a 1 ora di distanza", "Nessun esame dell'espettorato se l'IGRA è positivo"], "a": 1, "sec": ["5.3"]}, {"id": "7-10", "ch": 7, "n": 10, "stem": "La sensibilità dell'esame microscopico per BAAR è limitata perché la microscopia ottica convenzionale richiede in genere circa:", "opts": ["10 bacilli/ml", "100 bacilli/ml", "1.000 bacilli/ml", "10.000 bacilli/ml"], "a": 3, "sec": ["5.3"]}, {"id": "7-11", "ch": 7, "n": 11, "stem": "I BAAR osservati all'esame microscopico possono rappresentare TB o NTM, per cui l'identificazione di specie richiede:", "opts": ["Coltura e/o NAAT", "Emocromo completo", "Solo la VES", "Esame delle urine"], "a": 0, "sec": ["1", "5.3"]}, {"id": "7-12", "ch": 7, "n": 12, "stem": "Nel sospetto di TB attiva, IGRA/TST:", "opts": ["Stabiliscono la TB attiva se positivi", "Supportano ma non possono stabilire la TB attiva; un risultato negativo non esclude la malattia", "Escludono la TB attiva se negativi", "Sostituiscono l'esame dell'espettorato"], "a": 1, "sec": ["5.4"]}, {"id": "7-13", "ch": 7, "n": 13, "stem": "Il test per l'infezione tubercolare è in genere riservato a:", "opts": ["Tutti, ogni anno", "Solo a chi ha una radiografia del torace normale", "Solo a chi ha tosse da &lt;1 settimana", "Soggetti a rischio aumentato di sviluppare la malattia tubercolare che trarrebbero beneficio dal trattamento"], "a": 3, "sec": ["5.6"]}, {"id": "7-14", "ch": 7, "n": 14, "stem": "Negli adulti a rischio di progressione da basso a intermedio, l'IGRA è preferito al TST in particolare quando:", "opts": ["Non vi sono vaccinazioni pregresse", "Vi sono sintomi gravi di malattia tubercolare", "Vi è una pregressa vaccinazione con BCG o è improbabile che il paziente ritorni per la lettura del TST", "È presente una malattia cavitaria"], "a": 2, "sec": ["5.6"]}, {"id": "7-15", "ch": 7, "n": 15, "stem": "Prima di trattare l'infezione tubercolare dopo un TST/IGRA positivo, i medici devono:", "opts": ["Eseguire una valutazione per escludere la malattia tubercolare (anamnesi, esame obiettivo, radiografia del torace ± esame dell'espettorato)", "Iniziare subito isoniazide", "Ripetere l'IGRA ogni settimana per 1 mese", "Richiedere una TC dell'addome"], "a": 0, "sec": ["5.6"]}, {"id": "7-16", "ch": 7, "n": 16, "stem": "Se dopo un TST/IGRA positivo sono presenti sintomi e/o una radiografia del torace alterata, il passo successivo comprende:", "opts": ["Nessun ulteriore esame", "Coprocoltura", "Biopsia cutanea", "Tre campioni di espettorato per esame microscopico per BAAR, coltura e NAAT"], "a": 3, "sec": ["5.6"]}, {"id": "7-17", "ch": 7, "n": 17, "stem": "La terapia standard della TB polmonare farmacosensibile è organizzata in:", "opts": ["Una sola fase", "Una fase intensiva seguita da una fase di continuazione", "Solo cicli settimanali", "Terapia solo fino alla risoluzione della febbre"], "a": 1, "sec": ["6.1"]}, {"id": "7-18", "ch": 7, "n": 18, "stem": "La fase intensiva del regime tradizionale comprende:", "opts": ["Solo due farmaci", "Solo rifapentina e moxifloxacina", "Isoniazide, rifampicina, pirazinamide ed etambutolo", "Ceftriaxone e azitromicina"], "a": 2, "sec": ["6.1"]}, {"id": "7-19", "ch": 7, "n": 19, "stem": "La DOT è raccomandata principalmente per:", "opts": ["Garantire l'aderenza e prevenire l'emergenza di farmacoresistenza", "Ridurre immediatamente la tosse", "Sostituire la notifica alle autorità sanitarie", "Evitare la necessità di esami dell'espettorato"], "a": 0, "sec": ["6.1"]}, {"id": "7-20", "ch": 7, "n": 20, "stem": "Nei pazienti ricoverati con sospetta TB polmonare, un controllo delle infezioni appropriato comprende:", "opts": ["Solo precauzioni da contatto", "Isolamento per via aerea quando possibile; N95 per personale/visitatori; mascherina chirurgica per il paziente fuori dalla stanza AII", "Nessun isolamento se l'esame microscopico è negativo", "Solo guanti e camice"], "a": 1, "sec": ["8.3"]}, {"id": "8-1", "ch": 8, "n": 1, "stem": "La causa più comune di gastroenterite acuta in tutte le fasce d'età nel mondo è:", "opts": ["Norovirus", "Rotavirus", "<em>Campylobacter jejuni</em>", "<em>Giardia duodenalis</em>"], "a": 0, "sec": ["1.1"]}, {"id": "8-2", "ch": 8, "n": 2, "stem": "Diversi ospiti sviluppano vomito e crampi addominali 2-4 ore dopo aver mangiato bignè alla crema a una festa. La causa più probabile è:", "opts": ["Norovirus", "Enterotossina di <em>Staphylococcus aureus</em>", "<em>Shigella sonnei</em>", "<em>E. coli</em> produttore di tossina Shiga"], "a": 1, "sec": ["4.1"]}, {"id": "8-3", "ch": 8, "n": 3, "stem": "La tossina colerica causa diarrea:", "opts": ["Invadendo le cellule epiteliali del colon", "Inattivando le GTPasi della famiglia Rho", "Danneggiando le cellule endoteliali glomerulari", "ADP-ribosilando la proteina Gs, aumentando il cAMP e la secrezione di cloro"], "a": 3, "sec": ["3.1"]}, {"id": "8-4", "ch": 8, "n": 4, "stem": "Un bambino di 4 anni sviluppa diarrea ematica dopo aver mangiato un hamburger poco cotto. Sei giorni dopo è pallido, con piastrinopenia, schistociti e danno renale acuto. Il patogeno più probabile è:", "opts": ["<em>Campylobacter jejuni</em>", "<em>Vibrio cholerae</em>", "<em>E. coli</em> O157:H7 produttore di tossina Shiga", "<em>Giardia duodenalis</em>"], "a": 2, "sec": ["3.1"]}, {"id": "8-5", "ch": 8, "n": 5, "stem": "Nella sospetta infezione da STEC, gli antibiotici devono essere:", "opts": ["Somministrati empiricamente a tutti i pazienti", "Evitati, perché possono aumentare il rischio di SEU", "Somministrati solo sotto forma di fluorochinolone", "Somministrati solo agli adulti"], "a": 1, "sec": ["6.1"]}, {"id": "8-6", "ch": 8, "n": 6, "stem": "La sindrome di Guillain-Barré è una complicanza nota dell'infezione da:", "opts": ["<em>Campylobacter jejuni</em>", "Norovirus", "<em>Bacillus cereus</em>", "<em>Cryptosporidium</em>"], "a": 0, "sec": ["3.1"]}, {"id": "8-7", "ch": 8, "n": 7, "stem": "Il cardine del trattamento della diarrea acquosa acuta è:", "opts": ["La terapia empirica con fluorochinolone", "La loperamide per tutti i pazienti", "La reidratazione, preferibilmente con soluzione reidratante orale a ridotta osmolarità", "Il digiuno prolungato"], "a": 2, "sec": ["6.1"]}, {"id": "8-8", "ch": 8, "n": 8, "stem": "L'esame delle feci è indicato in un paziente con diarrea acuta che presenta:", "opts": ["Due evacuazioni di feci molli e nessun altro sintomo", "Diarrea acquosa lieve da un giorno", "Solo nausea", "Febbre, feci ematiche, dolore addominale intenso o sepsi"], "a": 3, "sec": ["5.1"]}, {"id": "8-9", "ch": 8, "n": 9, "stem": "<em>Clostridioides difficile</em> è meglio descritto come un:", "opts": ["Bacillo gram-negativo aerobio", "Cisti di protozoo", "Cocco gram-positivo aerobio", "Bacillo gram-positivo, anaerobio, sporigeno, produttore delle tossine A e B"], "a": 3, "sec": ["1.2"]}, {"id": "8-10", "ch": 8, "n": 10, "stem": "Le classi di antibiotici più fortemente associate alla CDI sono:", "opts": ["Tetracicline e aminoglicosidi", "Nitrofurantoina e fosfomicina", "Clindamicina, fluorochinoloni e cefalosporine", "Solo i macrolidi"], "a": 2, "sec": ["2.2"]}, {"id": "8-11", "ch": 8, "n": 11, "stem": "Il test per CDI è appropriato in un paziente ricoverato con:", "opts": ["≥3 evacuazioni di feci non formate in 24 ore, senza lassativi nelle 48 ore precedenti", "Feci formate e febbre", "Nessun sintomo, dopo aver completato il trattamento per CDI", "Diarrea insorta il giorno dopo un lassativo"], "a": 0, "sec": ["5.2"]}, {"id": "8-12", "ch": 8, "n": 12, "stem": "Un paziente con diarrea ha un NAAT per <em>C. difficile</em> positivo e un EIA per tossine negativo. L'interpretazione migliore è:", "opts": ["La CDI è esclusa", "<em>C. difficile</em> è presente ma la tossina non è rilevata: colonizzazione o CDI, da decidere clinicamente", "CDI fulminante", "Errore di laboratorio, ripetere il test ogni giorno"], "a": 1, "sec": ["5.2"]}, {"id": "8-13", "ch": 8, "n": 13, "stem": "Secondo le attuali linee guida, il trattamento preferito per un episodio iniziale di CDI è:", "opts": ["Vancomicina e.v.", "Metronidazolo orale", "Fidaxomicina", "Loperamide più probiotici"], "a": 2, "sec": ["6.2"]}, {"id": "8-14", "ch": 8, "n": 14, "stem": "La vancomicina e.v. non si usa per trattare la CDI perché:", "opts": ["<em>C. difficile</em> è resistente alla vancomicina", "Causa megacolon tossico", "È più costosa della vancomicina orale", "Non raggiunge il lume colico"], "a": 3, "sec": ["6.2"]}, {"id": "8-15", "ch": 8, "n": 15, "stem": "Un paziente con CDI sviluppa ipotensione, distensione addominale e ileo. La gestione più appropriata è:", "opts": ["Il solo metronidazolo orale", "Vancomicina orale/rettale più metronidazolo e.v., con consulenza chirurgica precoce", "Loperamide e liquidi", "Attendere la ripetizione dell'esame delle feci"], "a": 1, "sec": ["6.2"]}, {"id": "8-16", "ch": 8, "n": 16, "stem": "Dopo un trattamento efficace della CDI, un \"test di guarigione\":", "opts": ["Non è raccomandato, perché tossina e NAAT possono restare positivi", "È obbligatorio prima della dimissione", "Va eseguito ogni settimana per 8 settimane", "Va eseguito solo con EIA per tossine"], "a": 0, "sec": ["7.2"]}, {"id": "8-17", "ch": 8, "n": 17, "stem": "Il trattamento raccomandato per una seconda recidiva di CDI o successive è:", "opts": ["Ripetere il metronidazolo orale", "Il trapianto di microbiota fecale dopo la terapia antibiotica", "La vancomicina e.v.", "Nessun trattamento"], "a": 1, "sec": ["6.2"]}, {"id": "8-18", "ch": 8, "n": 18, "stem": "Durante un focolaio di CDI, il metodo migliore di igiene delle mani è:", "opts": ["Solo il gel idroalcolico", "Nessuna igiene delle mani se si indossano i guanti", "Il lavaggio con acqua e sapone", "Solo la frizione con clorexidina"], "a": 2, "sec": ["8.2"]}, {"id": "8-19", "ch": 8, "n": 19, "stem": "Quale affermazione sul vaccino anti-rotavirus è corretta?", "opts": ["È un vaccino vivo orale somministrato nel primo anno di vita e raccomandato in tutti i programmi nazionali", "È un vaccino iniettabile ad anatossina per adulti", "Si somministra solo ai viaggiatori", "Protegge anche dal norovirus"], "a": 0, "sec": ["8.1"]}, {"id": "8-20", "ch": 8, "n": 20, "stem": "Gli antimotilità come la loperamide:", "opts": ["Sono raccomandati in tutti i bambini con diarrea", "Sono la terapia di prima linea della CDI", "Sono sicuri nella diarrea ematica con febbre elevata", "Vanno evitati nella diarrea ematica, nella sospetta infezione da STEC e nella CDI"], "a": 3, "sec": ["6.1"]}, {"id": "9-1", "ch": 9, "n": 1, "stem": "La causa più comune di cistite acuta non complicata nelle giovani donne è:", "opts": ["<em>Staphylococcus saprophyticus</em>", "<em>Escherichia coli</em>", "<em>Enterococcus faecalis</em>", "<em>Pseudomonas aeruginosa</em>"], "a": 1, "sec": ["1.1"]}, {"id": "9-2", "ch": 9, "n": 2, "stem": "Un microrganismo produttore di ureasi associato a urine alcaline e calcoli di struvite è:", "opts": ["<em>Escherichia coli</em>", "<em>Enterococcus faecalis</em>", "<em>Streptococcus</em> di gruppo B", "<em>Proteus mirabilis</em>"], "a": 3, "sec": ["1.2"]}, {"id": "9-3", "ch": 9, "n": 3, "stem": "Nella maggior parte delle infezioni delle vie urinarie, i batteri raggiungono vescica e rene:", "opts": ["Risalendo dall'area periuretrale attraverso l'uretra", "Attraverso il circolo ematico durante una batteriemia", "Attraverso i vasi linfatici", "Per diffusione diretta dalla parete intestinale"], "a": 0, "sec": ["3.1"]}, {"id": "9-4", "ch": 9, "n": 4, "stem": "Il test dei nitriti urinari può essere negativo nonostante una vera IVU causata da:", "opts": ["<em>Escherichia coli</em>", "<em>Klebsiella pneumoniae</em>", "<em>Enterococcus faecalis</em>", "<em>Proteus mirabilis</em>"], "a": 2, "sec": ["5.1"]}, {"id": "9-5", "ch": 9, "n": 5, "stem": "In una donna asintomatica non in gravidanza, la batteriuria asintomatica è definita come:", "opts": ["≥10³ UFC/ml in un singolo campione minzionale", "La sola piuria allo stick", "≥10⁵ UFC/ml dello stesso microrganismo in due campioni minzionali consecutivi", "Qualsiasi crescita batterica in un campione minzionale"], "a": 2, "sec": ["5.2"]}, {"id": "9-6", "ch": 9, "n": 6, "stem": "Lo screening e il trattamento della batteriuria asintomatica sono raccomandati:", "opts": ["Nelle donne in gravidanza", "Negli anziani ospiti di strutture di lungodegenza", "Nelle donne con diabete", "Nei pazienti con catetere urinario a lungo termine"], "a": 0, "sec": ["6.6"]}, {"id": "9-7", "ch": 9, "n": 7, "stem": "L'IVU ricorrente è definita come:", "opts": ["≥1 infezione in 12 mesi", "≥2 infezioni in 6 mesi o ≥3 infezioni in 12 mesi", "≥4 infezioni in 6 mesi", "≥2 infezioni in 24 mesi"], "a": 1, "sec": ["2.1"]}, {"id": "9-8", "ch": 9, "n": 8, "stem": "Quale farmaco NON è appropriato nella pielonefrite acuta?", "opts": ["Ceftriaxone", "Ciprofloxacina (se l'isolato è sensibile)", "Piperacillina-tazobactam", "Nitrofurantoina"], "a": 3, "sec": ["6.3"]}, {"id": "9-9", "ch": 9, "n": 9, "stem": "Un'opzione di prima linea nella cistite acuta non complicata è:", "opts": ["Ciprofloxacina", "Amoxicillina", "Ceftriaxone", "Fosfomicina trometamolo"], "a": 3, "sec": ["6.2"]}, {"id": "9-10", "ch": 9, "n": 10, "stem": "Un paziente con pielonefrite ha ancora febbre dopo 72 ore di terapia appropriata. Il passo successivo migliore è:", "opts": ["Proseguire la stessa terapia senza indagini", "Un imaging (preferibilmente TC) per escludere ostruzione, ascesso o pielonefrite enfisematosa", "Sospendere tutti gli antibiotici", "Ripetere solo lo stick urinario"], "a": 1, "sec": ["5.4", "7.2"]}, {"id": "9-11", "ch": 9, "n": 11, "stem": "La soglia colturale per la CAUTI in un paziente cateterizzato sintomatico è:", "opts": ["≥10³ UFC/ml", "≥10⁵ UFC/ml in due campioni consecutivi", "≥10⁸ UFC/ml", "La sola piuria, senza coltura"], "a": 0, "sec": ["5.2"]}, {"id": "9-12", "ch": 9, "n": 12, "stem": "Un paziente con catetere urinario in sede da 3 settimane sviluppa febbre. Prima di iniziare gli antibiotici, il campione di urina va raccolto:", "opts": ["Dalla sacca di drenaggio", "Aspirando dal tubo del vecchio catetere", "Da un catetere appena inserito, dopo aver sostituito quello vecchio", "Nei pazienti cateterizzati non serve alcun campione"], "a": 2, "sec": ["5.2"]}, {"id": "9-13", "ch": 9, "n": 13, "stem": "Secondo le attuali linee guida, un paziente con IVU complicata in miglioramento con una terapia efficace deve ricevere:", "opts": ["5-7 giorni di un fluorochinolone o 7 giorni di un farmaco non fluorochinolonico, anche in presenza di batteriemia da gram-negativi", "14 giorni in tutti i casi", "21 giorni se le emocolture sono positive", "Una dose singola"], "a": 0, "sec": ["6.4"]}, {"id": "9-14", "ch": 9, "n": 14, "stem": "Un uomo con IVU febbrile e sospetta prostatite batterica acuta può necessitare di una durata del trattamento di:", "opts": ["Una dose singola", "3 giorni", "5 giorni", "10-14 giorni"], "a": 3, "sec": ["6.4"]}, {"id": "9-15", "ch": 9, "n": 15, "stem": "La pielonefrite enfisematosa si verifica tipicamente nei pazienti con:", "opts": ["Cistite ricorrente in giovani donne sane", "Diabete mellito scarsamente controllato", "Batteriuria asintomatica in gravidanza", "Catetere urinario a breve termine"], "a": 1, "sec": ["4.3"]}, {"id": "9-16", "ch": 9, "n": 16, "stem": "Secondo le evidenze attuali, i prodotti a base di cranberry mostrano un beneficio scarso o nullo:", "opts": ["Nei bambini", "Nelle donne con IVU ricorrenti", "Negli anziani istituzionalizzati, nelle donne in gravidanza e nei pazienti con vescica neurologica", "Nelle persone predisposte a IVU dopo interventi medici"], "a": 2, "sec": ["8.1"]}, {"id": "9-17", "ch": 9, "n": 17, "stem": "Quale delle seguenti NON è una misura non antibiotica con una certa efficacia nella prevenzione delle IVU ricorrenti nella donna?", "opts": ["Estrogeni vaginali nelle donne in postmenopausa", "Metenamina ippurato", "Screening e trattamento di routine della batteriuria asintomatica", "Profilassi immunoattiva con lisati batterici"], "a": 2, "sec": ["8.1"]}, {"id": "9-18", "ch": 9, "n": 18, "stem": "<em>Staphylococcus aureus</em> viene isolato dalle urine di un paziente febbrile senza catetere urinario. L'interpretazione migliore è:", "opts": ["Possibile localizzazione ematogena; vanno eseguite emocolture", "Sempre una contaminazione", "La causa tipica di cistite non complicata", "Non è necessaria alcuna ulteriore azione"], "a": 0, "sec": ["1.1"]}, {"id": "9-19", "ch": 9, "n": 19, "stem": "Quale classe di antibiotici è il trattamento di scelta delle infezioni gravi da Enterobacterales produttori di ESBL?", "opts": ["Cefalosporine di terza generazione", "Penicilline", "Macrolidi", "Carbapenemi"], "a": 3, "sec": ["6.3"]}, {"id": "9-20", "ch": 9, "n": 20, "stem": "La misura più efficace per prevenire la CAUTI è:", "opts": ["La profilassi antibiotica sistemica di routine", "Evitare i cateteri non necessari e rimuoverli il prima possibile", "Sostituire i cateteri a intervalli settimanali fissi", "L'irrigazione vescicale con antimicrobici"], "a": 1, "sec": ["8.2"]}, {"id": "10-1", "ch": 10, "n": 1, "stem": "La causa più comune di cellulite non purulenta in un adulto immunocompetente è:", "opts": ["<em>Pseudomonas aeruginosa</em>", "Streptococchi β-emolitici", "<em>Escherichia coli</em>", "<em>Clostridium perfringens</em>"], "a": 1, "sec": ["1.1"]}, {"id": "10-2", "ch": 10, "n": 2, "stem": "Secondo la definizione FDA, una ABSSSI richiede un'area minima della lesione di:", "opts": ["5 cm²", "25 cm²", "50 cm²", "75 cm²"], "a": 3, "sec": ["2.1"]}, {"id": "10-3", "ch": 10, "n": 3, "stem": "Rispetto alla cellulite, l'erisipela è caratterizzata da:", "opts": ["Un margine rilevato e nettamente demarcato, che riflette il coinvolgimento del derma superficiale e dei linfatici superficiali", "Coinvolgimento della fascia profonda", "Una prevalenza di bacilli gram-negativi", "Un esordio lento senza febbre"], "a": 0, "sec": ["4.1"]}, {"id": "10-4", "ch": 10, "n": 4, "stem": "Quale reperto suggerisce più fortemente una fascite necrotizzante anziché una semplice cellulite?", "opts": ["Calore sopra la lesione", "Febbricola", "Dolore sproporzionato rispetto ai reperti, con aree di anestesia cutanea", "Linfoadenopatia inguinale dolente"], "a": 2, "sec": ["4.3"]}, {"id": "10-5", "ch": 10, "n": 5, "stem": "Una donna di 78 anni, afebbrile, con insufficienza venosa cronica, presenta da diverse settimane cute arrossata, desquamante e pruriginosa a entrambe le gambe. La diagnosi più probabile è:", "opts": ["Cellulite streptococcica bilaterale", "Fascite necrotizzante", "Dermatite da stasi", "Gangrena gassosa"], "a": 2, "sec": ["4.5"]}, {"id": "10-6", "ch": 10, "n": 6, "stem": "In un paziente con cellulite tipica non complicata, le emocolture sono:", "opts": ["Non raccomandate di routine; riservate a situazioni come neutropenia, chemioterapia, lesioni da immersione o morsi di animale", "Obbligatorie prima di qualsiasi antibiotico", "Positive nella maggior parte dei casi", "Il modo migliore per identificare MRSA"], "a": 0, "sec": ["5.2"]}, {"id": "10-7", "ch": 10, "n": 7, "stem": "Il test al letto del paziente più utile per individuare un ascesso occulto in un'area di cellulite è:", "opts": ["La radiografia standard", "La coltura di un tampone cutaneo", "Il titolo antistreptolisinico O", "L'ecografia point-of-care"], "a": 3, "sec": ["5.3"]}, {"id": "10-8", "ch": 10, "n": 8, "stem": "Lo score LRINEC comprende:", "opts": ["Procalcitonina, lattato e conta piastrinica", "Proteina C reattiva, conta leucocitaria, emoglobina, sodio, creatinina e glicemia", "Creatinchinasi, mioglobina e potassio", "Risultati delle emocolture e colorazione di Gram della ferita"], "a": 1, "sec": ["5.4"]}, {"id": "10-9", "ch": 10, "n": 9, "stem": "Il gold standard per la diagnosi di infezione necrotizzante dei tessuti molli è:", "opts": ["L'esplorazione chirurgica", "Uno score LRINEC ≥6", "La RM dell'arto", "Le emocolture"], "a": 0, "sec": ["5.4"]}, {"id": "10-10", "ch": 10, "n": 10, "stem": "Il trattamento principale di un ascesso cutaneo non complicato è:", "opts": ["La sola penicillina orale", "Antibiotici topici", "Incisione e drenaggio", "Solo impacchi caldi"], "a": 2, "sec": ["6.2"]}, {"id": "10-11", "ch": 10, "n": 11, "stem": "In un ascesso cutaneo drenato, in un contesto con MRSA frequente, l'aggiunta di cotrimossazolo o clindamicina:", "opts": ["Aumenta la mortalità", "Non ha effetto su alcun esito", "È necessaria solo nei bambini", "Aumenta modestamente il tasso di guarigione clinica"], "a": 3, "sec": ["6.2"]}, {"id": "10-12", "ch": 10, "n": 12, "stem": "Il trattamento preferito della cellulite non purulenta lieve in un paziente ambulatoriale è:", "opts": ["Vancomicina e.v.", "Un β-lattamico antistreptococcico orale", "Ciprofloxacina orale", "Incisione e drenaggio"], "a": 1, "sec": ["6.3"]}, {"id": "10-13", "ch": 10, "n": 13, "stem": "Nei pazienti con cellulite non purulenta non complicata, l'aggiunta di cotrimossazolo alla cefalexina:", "opts": ["Ha raddoppiato il tasso di guarigione", "Non ha migliorato il tasso di guarigione nell'analisi per protocollo", "Era necessaria perché MRSA è la causa principale", "Ha ridotto la durata della terapia a 1 giorno"], "a": 1, "sec": ["6.3"]}, {"id": "10-14", "ch": 10, "n": 14, "stem": "Nella cellulite non complicata che migliora, la durata raccomandata della terapia antibiotica è:", "opts": ["1 giorno", "3 settimane", "6 settimane", "5-6 giorni, prolungata se l'infezione non è migliorata"], "a": 3, "sec": ["6.5"]}, {"id": "10-15", "ch": 10, "n": 15, "stem": "Nella fascite necrotizzante da <em>Streptococcus</em> di gruppo A si aggiunge la clindamicina principalmente perché:", "opts": ["Sopprime la produzione di tossine batteriche", "Copre <em>Pseudomonas aeruginosa</em>", "Penetra nel liquor", "Sostituisce la necessità della chirurgia"], "a": 0, "sec": ["6.6"]}, {"id": "10-16", "ch": 10, "n": 16, "stem": "Un uomo con cirrosi sviluppa bolle emorragiche e shock settico 24 ore dopo essersi tagliato la gamba mentre pescava in mare. Il patogeno più probabile è:", "opts": ["<em>Pasteurella multocida</em>", "<em>Erysipelothrix rhusiopathiae</em>", "<em>Vibrio vulnificus</em>", "<em>Aeromonas hydrophila</em>"], "a": 2, "sec": ["1.2"]}, {"id": "10-17", "ch": 10, "n": 17, "stem": "L'antibiotico orale empirico di scelta per un morso di cane infetto è:", "opts": ["Cefalexina", "La sola clindamicina", "Amoxicillina-clavulanato", "Il solo metronidazolo"], "a": 2, "sec": ["6.7"]}, {"id": "10-18", "ch": 10, "n": 18, "stem": "Ventiquattro ore dopo l'inizio di antibiotici appropriati per una cellulite, l'eritema si è esteso leggermente oltre il segno a penna, ma il paziente è afebbrile e si sente meglio. L'interpretazione migliore è:", "opts": ["Un aumento precoce dell'eritema può verificarsi e non è, da solo, un fallimento terapeutico; rivalutare", "È necessario passare immediatamente a un carbapenemico", "La fascite necrotizzante è confermata", "La diagnosi di cellulite è esclusa"], "a": 0, "sec": ["7.1"]}, {"id": "10-19", "ch": 10, "n": 19, "stem": "In un paziente con edema cronico degli arti inferiori e cellulite ricorrente, quale misura riduce le recidive?", "opts": ["Mupirocina topica a lungo termine sulla gamba", "Emocolture settimanali", "Riposo a letto", "Terapia compressiva"], "a": 3, "sec": ["8"]}, {"id": "10-20", "ch": 10, "n": 20, "stem": "Riguardo a vaccini e infezioni cutanee:", "opts": ["Un vaccino contro lo streptococco di gruppo A è raccomandato di routine", "Non esiste un vaccino autorizzato contro lo <em>Streptococcus</em> di gruppo A né contro <em>S. aureus</em>; dopo le ferite va verificato lo stato vaccinale antitetanico", "La vaccinazione contro <em>S. aureus</em> previene gli ascessi ricorrenti", "Il vaccino antipneumococcico previene l'erisipela"], "a": 1, "sec": ["8"]}, {"id": "11-1", "ch": 11, "n": 1, "stem": "La causa più comune di osteomielite in tutte le fasce d'età è:", "opts": ["<em>Staphylococcus aureus</em>", "<em>Escherichia coli</em>", "<em>Pseudomonas aeruginosa</em>", "<em>Mycobacterium tuberculosis</em>"], "a": 0, "sec": ["1.1"]}, {"id": "11-2", "ch": 11, "n": 2, "stem": "Un bambino di 2 anni ha un'osteomielite con colture standard negative. Quale microrganismo è più probabile e si rileva meglio con la PCR?", "opts": ["<em>Salmonella enterica</em>", "<em>Kingella kingae</em>", "<em>Haemophilus influenzae</em> tipo b", "<em>Candida albicans</em>"], "a": 1, "sec": ["1.1", "1.2"]}, {"id": "11-3", "ch": 11, "n": 3, "stem": "Quale associazione tra ospite e patogeno è classica?", "opts": ["Piede diabetico e <em>Kingella kingae</em>", "Ferita puntoria attraverso la scarpa e <em>Brucella</em>", "Lattante e <em>Cutibacterium acnes</em>", "Anemia falciforme e <em>Salmonella</em>"], "a": 3, "sec": ["1.1"]}, {"id": "11-4", "ch": 11, "n": 4, "stem": "Tre settimane dopo una protesi di ginocchio, un paziente presenta secrezione dalla ferita e una protesi dolente ma <strong>ben fissa</strong>. Il liquido articolare aspirato isola <em>S. aureus</em> sensibile alla rifampicina. La strategia più appropriata è:", "opts": ["Soli antibiotici orali, senza chirurgia", "Sostituzione in due tempi in tutti i casi", "Sbrigliamento, antibiotici e mantenimento dell'impianto (DAIR), con un regime contenente rifampicina", "Amputazione"], "a": 2, "sec": ["3.5", "6.7"]}, {"id": "11-5", "ch": 11, "n": 5, "stem": "Quale reperto da solo conferma un'infezione di protesi articolare?", "opts": ["Una proteina C reattiva elevata", "La febbre", "Una coltura positiva da un tampone della superficie della ferita", "Un tramite fistoloso comunicante con la protesi"], "a": 3, "sec": ["4.5", "5.7"]}, {"id": "11-6", "ch": 11, "n": 6, "stem": "Nella patogenesi dell'osteomielite cronica, un \"sequestro\" è:", "opts": ["Un frammento di osso necrotico che ospita batteri in biofilm", "Osso nuovo formatosi attorno all'infezione", "Un tramite fistoloso che drena verso la cute", "La cartilagine di accrescimento di un bambino"], "a": 0, "sec": ["3.2"]}, {"id": "11-7", "ch": 11, "n": 7, "stem": "Perché la spondilodiscite piogenica coinvolge tipicamente due vertebre adiacenti e il disco interposto?", "opts": ["Il disco è riccamente vascolarizzato negli adulti", "Ogni arteria segmentaria irrora i piatti vertebrali di due vertebre adiacenti", "I batteri si diffondono attraverso il liquor", "L'infezione inizia sempre nel processo spinoso"], "a": 1, "sec": ["3.4"]}, {"id": "11-8", "ch": 11, "n": 8, "stem": "Quale caratteristica favorisce una spondilite tubercolare rispetto a una piogenica?", "opts": ["Esordio acuto in pochi giorni", "Distruzione precoce del disco", "Coinvolgimento lombare isolato con piccolo ascesso", "Coinvolgimento toracico, relativo risparmio del disco e ampio ascesso \"freddo\""], "a": 3, "sec": ["3.4", "4.2"]}, {"id": "11-9", "ch": 11, "n": 9, "stem": "Il sintomo più comune dell'osteomielite vertebrale è:", "opts": ["Dolore rachideo dorsale/lombare o cervicale localizzato", "Febbre elevata in tutti i pazienti", "Paraplegia", "Rash cutaneo"], "a": 0, "sec": ["4.2"]}, {"id": "11-10", "ch": 11, "n": 10, "stem": "Un paziente con spondilodiscite sviluppa nuova debolezza agli arti inferiori e ritenzione urinaria. Il passo successivo più appropriato è:", "opts": ["Fisioterapia ambulatoriale", "Ripetere la proteina C reattiva tra 2 settimane", "RM urgente e valutazione chirurgica per ascesso epidurale", "Analgesici orali e dimissione"], "a": 2, "sec": ["4.2", "6.3"]}, {"id": "11-11", "ch": 11, "n": 11, "stem": "L'esame di imaging di scelta nella sospetta osteomielite vertebrale è:", "opts": ["La radiografia standard", "La RM con gadolinio", "L'ecografia", "La densitometria ossea"], "a": 1, "sec": ["5.3"]}, {"id": "11-12", "ch": 11, "n": 12, "stem": "Nella sospetta osteomielite vertebrale, una biopsia guidata da imaging di solito NON è necessaria quando:", "opts": ["Le emocolture isolano <em>S. aureus</em> e la RM è compatibile", "La proteina C reattiva è elevata", "Il paziente ha dolore rachideo notturno", "La radiografia standard è normale"], "a": 0, "sec": ["5.4"]}, {"id": "11-13", "ch": 11, "n": 13, "stem": "Un paziente stabile e neurologicamente integro ha reperti RM di spondilodiscite ed emocolture negative. Il passo successivo migliore è:", "opts": ["Iniziare antibiotici empirici per 6 settimane senza ulteriori esami", "Iniziare corticosteroidi", "Biopsia percutanea con ago guidata da imaging per coltura e istologia prima degli antibiotici", "Ripetere la RM tra 6 mesi"], "a": 2, "sec": ["5.4", "6.1"]}, {"id": "11-14", "ch": 11, "n": 14, "stem": "Le colture da un tampone superficiale di un tramite fistoloso cronico:", "opts": ["Sono il gold standard dell'osteomielite cronica", "Sono sempre sterili", "Sostituiscono la biopsia ossea nell'osteomielite del piede diabetico", "Non sono affidabili, perché riflettono la colonizzazione anziché i patogeni dell'osso"], "a": 3, "sec": ["5.5"]}, {"id": "11-15", "ch": 11, "n": 15, "stem": "Nell'osteomielite vertebrale piogenica, 6 settimane di antibiotici rispetto a 12 settimane sono:", "opts": ["Inferiori, con più recidive", "Ugualmente efficaci per la guarigione", "Associate a più decessi", "Accettabili solo per MRSA"], "a": 1, "sec": ["6.3"]}, {"id": "11-16", "ch": 11, "n": 16, "stem": "Quale paziente con osteomielite vertebrale ematogena è candidato a un ciclo più lungo (almeno 8 settimane)?", "opts": ["Un paziente con infezione da MSSA e nessun ascesso", "Un paziente con infezione streptococcica e funzione renale normale", "Un paziente con infezione da MRSA e un ascesso dello psoas non drenato", "Un paziente la cui proteina C reattiva si è normalizzata dopo 2 settimane"], "a": 2, "sec": ["6.3"]}, {"id": "11-17", "ch": 11, "n": 17, "stem": "Nelle infezioni osteoarticolari, la terapia orale precoce rispetto alla terapia endovenosa è:", "opts": ["Ugualmente efficace, con meno complicanze da catetere", "Inferiore in tutti i sottogruppi", "Accettabile solo nei bambini", "Associata a più fallimenti terapeutici"], "a": 0, "sec": ["6.2"]}, {"id": "11-18", "ch": 11, "n": 18, "stem": "Quale delle seguenti è un'indicazione alla chirurgia nell'osteomielite vertebrale?", "opts": ["Febbre in seconda giornata di terapia", "Lieve dolore rachideo in miglioramento con il trattamento", "VES elevata alla diagnosi", "Deficit neurologico progressivo o instabilità vertebrale"], "a": 3, "sec": ["6.3"]}, {"id": "11-19", "ch": 11, "n": 19, "stem": "In un paziente con ulcera del piede diabetico, quale combinazione è raccomandata come approccio diagnostico iniziale all'osteomielite?", "opts": ["Solo coltura da tampone e procalcitonina", "Probe-to-bone test, marcatori di infiammazione (VES) e radiografia standard", "Solo scintigrafia ossea", "Solo l'impressione clinica"], "a": 1, "sec": ["5.6"]}, {"id": "11-20", "ch": 11, "n": 20, "stem": "In un paziente in miglioramento clinico durante il trattamento di una spondilodiscite, quale affermazione sul follow-up è corretta?", "opts": ["La RM va ripetuta ogni 2 settimane", "Gli antibiotici vanno sospesi quando la RM si normalizza", "La ripetizione di routine della RM non è raccomandata, perché le alterazioni RM possono persistere o sembrare peggiorate nonostante una buona risposta", "Il follow-up può terminare alla fine della terapia"], "a": 2, "sec": ["7"]}, {"id": "12-1", "ch": 12, "n": 1, "stem": "La brucellosi è descritta meglio come:", "opts": ["Un'infezione esclusivamente umana trasmessa con le goccioline respiratorie", "Un'infezione protozoaria trasmessa da zecche", "Un'infezione zoonotica trasmessa da animali infetti con l'ingestione di alimenti o il contatto con tessuti o liquidi biologici", "Un'elmintiasi acquisita da lumache d'acqua dolce"], "a": 2, "sec": ["2"]}, {"id": "12-2", "ch": 12, "n": 2, "stem": "Il meccanismo più frequente di trasmissione all'uomo è:", "opts": ["Il consumo di latticini non pastorizzati", "La puntura di zanzara", "La trasmissione sessuale", "La trasmissione oro-fecale da uomo a uomo"], "a": 0, "sec": ["2"]}, {"id": "12-3", "ch": 12, "n": 3, "stem": "Quale categoria professionale è classicamente a rischio di brucellosi?", "opts": ["Impiegati d'ufficio", "Cassieri di negozi", "Insegnanti", "Addetti alla macellazione"], "a": 3, "sec": ["2"]}, {"id": "12-4", "ch": 12, "n": 4, "stem": "Quale affermazione sulla trasmissione interumana è più corretta?", "opts": ["È la via predominante nel mondo", "È rara ma è stata descritta (es. trasfusione, allattamento al seno, contatto sessuale, trasmissione congenita)", "Non si verifica mai", "Avviene solo con le goccioline respiratorie"], "a": 1, "sec": ["2"]}, {"id": "12-5", "ch": 12, "n": 5, "stem": "Il periodo di incubazione tipico è:", "opts": ["2–4 settimane (talvolta mesi)", "1–3 giorni", "6–12 mesi", "Sempre superiore a 1 anno"], "a": 0, "sec": ["4.1"]}, {"id": "12-6", "ch": 12, "n": 6, "stem": "Un insieme tipico di sintomi comprende:", "opts": ["Diarrea acquosa acuta ed esantema", "Ittero grave entro 24 ore", "Solo emottisi e dolore toracico pleuritico", "Febbre a esordio insidioso, malessere, sudorazioni notturne e artralgie"], "a": 3, "sec": ["4.1"]}, {"id": "12-7", "ch": 12, "n": 7, "stem": "Quale reperto obiettivo può essere presente ma è aspecifico?", "opts": ["Escara patognomonica", "Macchie di Koplik", "Epatomegalia e/o splenomegalia", "Meningismo in tutti i casi"], "a": 2, "sec": ["4.1"]}, {"id": "12-8", "ch": 12, "n": 8, "stem": "La complicanza focale più frequente è:", "opts": ["L'endocardite", "La malattia osteoarticolare", "La neurobrucellosi", "L'ascesso polmonare"], "a": 1, "sec": ["4.2"]}, {"id": "12-9", "ch": 12, "n": 9, "stem": "La sacroileite nella brucellosi è:", "opts": ["Bilaterale in quasi tutti i casi", "Sempre indolore", "Sempre cervicale", "Spesso monolaterale e una manifestazione importante nei giovani adulti"], "a": 3, "sec": ["4.2"]}, {"id": "12-10", "ch": 12, "n": 10, "stem": "L'endocardite brucellare è caratterizzata meglio come:", "opts": ["Non comune, ma principale causa di morte attribuibile alla brucellosi", "Frequente e benigna", "Sempre destra", "Mai a carico della valvola aortica"], "a": 0, "sec": ["4.2"]}, {"id": "12-11", "ch": 12, "n": 11, "stem": "Una diagnosi definitiva si può porre con:", "opts": ["Una singola sierologia a basso titolo in qualsiasi contesto", "La sola PCR, senza contesto clinico", "La coltura da sangue, liquidi biologici o tessuti, OPPURE un aumento di almeno 4 volte del titolo anticorpale su sieri appaiati", "Il solo imaging"], "a": 2, "sec": ["5.2"]}, {"id": "12-12", "ch": 12, "n": 12, "stem": "Una diagnosi presuntiva si può porre con:", "opts": ["Un titolo SAT inferiore a 1:40", "Un titolo SAT ≥1:160 dopo l'esordio dei sintomi", "Emocolture negative", "Enzimi epatici normali"], "a": 1, "sec": ["5.2"]}, {"id": "12-13", "ch": 12, "n": 13, "stem": "Gli esami diagnostici iniziali nel sospetto di brucellosi devono comprendere:", "opts": ["Emocolture ed esami sierologici", "Solo la coprocoltura", "La biopsia cutanea", "Solo la ricerca dell'antigene urinario"], "a": 0, "sec": ["5.1"]}, {"id": "12-14", "ch": 12, "n": 14, "stem": "Quale affermazione sulla coltura è più corretta?", "opts": ["La coltura non è mai utile", "La midollocoltura è meno sensibile dell'emocoltura", "L'emocoltura è sempre positiva nella malattia cronica", "La coltura è il gold standard e dimostra un'infezione in atto, ma la sua sensibilità è variabile"], "a": 3, "sec": ["5.3"]}, {"id": "12-15", "ch": 12, "n": 15, "stem": "Rispetto all'emocoltura, la midollocoltura è:", "opts": ["Meno sensibile e più lenta", "Mai positiva", "Più sensibile e meno influenzata da una precedente terapia antibiotica", "Utile solo nei bambini"], "a": 2, "sec": ["5.3"]}, {"id": "12-16", "ch": 12, "n": 16, "stem": "Quale affermazione sulla sierologia è più corretta?", "opts": ["La sierologia non dà mai reazioni crociate con altri batteri", "La sierologia va interpretata nel contesto clinico ed epidemiologico e la SAT può essere falsamente negativa nell'infezione cronica", "La SAT è sempre positiva nell'infezione cronica", "L'ELISA non si usa mai"], "a": 1, "sec": ["5.4"]}, {"id": "12-17", "ch": 12, "n": 17, "stem": "I principi chiave del trattamento comprendono:", "opts": ["Terapia di associazione e durata prolungata per ridurre le recidive", "Una monoterapia di 7 giorni è sufficiente", "Gli antibiotici non sono necessari", "È efficace solo la terapia topica"], "a": 0, "sec": ["6.1"]}, {"id": "12-18", "ch": 12, "n": 18, "stem": "Quale delle seguenti associazioni antibiotiche NON si usa nel trattamento della brucellosi?", "opts": ["Doxiciclina più un aminoglicoside", "Doxiciclina più rifampicina", "Ceftriaxone più rifampicina più doxiciclina", "Ampicillina più cefazolina"], "a": 3, "sec": ["6.2", "6.3"]}, {"id": "12-19", "ch": 12, "n": 19, "stem": "La recidiva si verifica più spesso:", "opts": ["Entro 24 ore", "Entro 6 mesi dalla fine del trattamento (fino a 12 mesi)", "Solo dopo 10 anni", "Solo durante la terapia"], "a": 1, "sec": ["7"]}, {"id": "12-20", "ch": 12, "n": 20, "stem": "Quale affermazione sulla prevenzione è più corretta?", "opts": ["È ampiamente disponibile un vaccino per l'uomo", "Conta solo il controllo delle zanzare", "Evitare i latticini a base di latte crudo e adottare precauzioni professionali; non esiste un vaccino per l'uomo", "Dopo un'esposizione in laboratorio non servono indicazioni post-esposizione"], "a": 2, "sec": ["8"]}, {"id": "13-1", "ch": 13, "n": 1, "stem": "Quale affermazione descrive meglio la forma di <em>Leishmania</em> presente nei tessuti umani?", "opts": ["Amastigoti intracellulari nei macrofagi", "Promastigoti extracellulari nel plasma", "Sporozoiti intracellulari negli epatociti", "Trofozoiti extracellulari nel lume intestinale"], "a": 0, "sec": ["1"]}, {"id": "13-2", "ch": 13, "n": 2, "stem": "Nel flebotomo, gli amastigoti ingeriti si sviluppano in promastigoti in:", "opts": ["4-14 ore", "24-48 ore", "4-14 giorni", "4-14 settimane"], "a": 2, "sec": ["1"]}, {"id": "13-3", "ch": 13, "n": 3, "stem": "L'evoluzione più tipica della lesione nella leishmaniosi cutanea localizzata è:", "opts": ["Vescicole dolorose → croste a distribuzione dermatomerica", "Escara rapidamente necrotica con dolore intenso entro 24 ore", "Orticaria diffusa con angioedema", "Papula → nodulo/placca → ulcera di solito indolore con margine indurito"], "a": 3, "sec": ["4.1"]}, {"id": "13-4", "ch": 13, "n": 4, "stem": "Quale reperto è compatibile con una leishmaniosi cutanea?", "opts": ["Esordio acuto con risoluzione in 48 ore", "Linfangite nodulare e linfoadenopatia regionale", "Neuropatia prominente come caratteristica distintiva", "Ulcere sempre intensamente dolorose"], "a": 1, "sec": ["4.1"]}, {"id": "13-5", "ch": 13, "n": 5, "stem": "Nell'emisfero occidentale, la leishmaniosi mucosa è causata più spesso da:", "opts": ["Solo <em>Leishmania</em> sottogenere <em>Leishmania</em>", "<em>Trypanosoma cruzi</em>", "Specie di <em>Leishmania</em> (<em>Viannia</em>)", "<em>Plasmodium falciparum</em>"], "a": 2, "sec": ["4.2"]}, {"id": "13-6", "ch": 13, "n": 6, "stem": "Quale sintomo è caratteristico della leishmaniosi mucosa?", "opts": ["Congestione od ostruzione nasale con sanguinamento mucoso", "Dolore toracico pleuritico", "Ematuria con dolore al fianco", "Solo diarrea acquosa acuta"], "a": 0, "sec": ["4.2"]}, {"id": "13-7", "ch": 13, "n": 7, "stem": "La sindrome classica della leishmaniosi viscerale (kala-azar) comprende più comunemente:", "opts": ["Febbre acuta con rash e artralgie nell'arco di 24 ore", "Linfoadenite cervicale isolata senza sintomi sistemici", "Deficit puramente neurologici senza reperti sistemici", "Malessere subacuto, febbre, calo ponderale e splenomegalia nell'arco di settimane o mesi"], "a": 3, "sec": ["4.3"]}, {"id": "13-8", "ch": 13, "n": 8, "stem": "La diagnosi definitiva di leishmaniosi cutanea richiede:", "opts": ["Il solo aspetto clinico", "La dimostrazione del parassita in un campione clinico mediante istologia, coltura o PCR", "La sierologia", "La risposta ad antibiotici empirici"], "a": 1, "sec": ["5.1"]}, {"id": "13-9", "ch": 13, "n": 9, "stem": "Per massimizzare la resa diagnostica nella LC, l'approccio iniziale preferito (se possibile) è:", "opts": ["Istologia, coltura e PCR sul campione iniziale", "Solo sierologia", "Solo coltura", "Nessun test se la lesione è indolore"], "a": 0, "sec": ["5.1"]}, {"id": "13-10", "ch": 13, "n": 10, "stem": "Quale affermazione sulla sierologia nella leishmaniosi cutanea è più accurata?", "opts": ["È il test di conferma preferito", "Distingue in modo affidabile l'infezione attiva da quella pregressa", "È necessaria prima della biopsia", "La sierologia disponibile in commercio non ha alcun ruolo clinico nella diagnosi di LC"], "a": 3, "sec": ["5.1"]}, {"id": "13-11", "ch": 13, "n": 11, "stem": "Nella LC, quale sede è preferita per una biopsia punch di una lesione ulcerata?", "opts": ["Solo il centro del fondo dell'ulcera", "Cute distante di aspetto normale", "Il margine rilevato dell'ulcera", "L'escara sovrastante, senza sbrigliamento"], "a": 2, "sec": ["5.1"]}, {"id": "13-12", "ch": 13, "n": 12, "stem": "All'istopatologia, quale caratteristica è essenziale per identificare gli amastigoti di <em>Leishmania</em>?", "opts": ["Forme di lievito gemmanti", "La visualizzazione del cinetoplasto", "Bacilli alcol-acido resistenti", "Ife settate"], "a": 1, "sec": ["5.1"]}, {"id": "13-13", "ch": 13, "n": 13, "stem": "Un metodo diagnostico rapido al letto del paziente per la LC è:", "opts": ["Preparato con KOH per ife", "Agglutinazione al lattice per l'antigene criptococcico", "Striscio sottile e goccia spessa per la malaria", "Striscio tipo Tzanck da raschiato della lesione colorato con Wright-Giemsa"], "a": 3, "sec": ["5.1"]}, {"id": "13-14", "ch": 13, "n": 14, "stem": "Quale condizione è una nota simulatrice della leishmaniosi cutanea?", "opts": ["Sporotricosi", "Appendicite acuta", "Otite media acuta", "Miastenia gravis"], "a": 0, "sec": ["5.1"]}, {"id": "13-15", "ch": 13, "n": 15, "stem": "Tra le condizioni che simulano la LC, quale caratteristica orienta verso la lebbra?", "opts": ["Cronicità", "Localizzazione sulla cute esposta", "Neuropatia", "Margine indurito dell'ulcera"], "a": 2, "sec": ["5.1"]}, {"id": "13-16", "ch": 13, "n": 16, "stem": "La diagnosi definitiva di leishmaniosi viscerale richiede:", "opts": ["Un test rK39 positivo da solo", "La dimostrazione del parassita mediante striscio o coltura di tessuto (di solito midollo osseo o milza)", "Uno striscio per malaria negativo", "Transaminasi elevate"], "a": 1, "sec": ["5.2"]}, {"id": "13-17", "ch": 13, "n": 17, "stem": "Quale affermazione sulla sierologia nella leishmaniosi viscerale è più accurata?", "opts": ["È una prova definitiva di LV attiva in tutti i contesti", "È utile per valutare la guarigione perché si negativizza rapidamente", "È sempre negativa nei pazienti immunocompetenti", "Un test positivo non è una prova definitiva di LV attiva e va interpretato nel contesto clinico ed epidemiologico"], "a": 3, "sec": ["5.2"]}, {"id": "13-18", "ch": 13, "n": 18, "stem": "Nella coinfezione HIV–LV, quale affermazione diagnostica è più accurata?", "opts": ["La sensibilità sierologica è ridotta, mentre le elevate cariche parassitarie aumentano la sensibilità di emocoltura e test molecolari", "La sierologia è più sensibile della PCR", "La LV non può verificarsi", "È utile solo la biopsia cutanea"], "a": 0, "sec": ["5.2"]}, {"id": "13-19", "ch": 13, "n": 19, "stem": "Quale caratteristica definisce una leishmaniosi cutanea \"complicata\" e in genere supporta la terapia sistemica?", "opts": ["Una singola piccola lesione in un ospite immunocompetente", "Una lesione già in guarigione spontanea", "Lesioni sul volto, dita delle mani, dita dei piedi o genitali", "Infezione acquisita al di fuori delle aree associate al rischio di LM"], "a": 2, "sec": ["6.1"]}, {"id": "13-20", "ch": 13, "n": 20, "stem": "Quattro-sei settimane dopo il trattamento della LC, la risposta attesa è:", "opts": ["La guarigione completa della lesione in tutti i casi", "Dimensioni della lesione ridotte di oltre il 50%, miglioramento dell'infiammazione e riepitelizzazione, e nessuna nuova lesione", "Qualsiasi peggioramento indica sempre un fallimento terapeutico", "Campionamento parassitologico di routine, anche se la lesione sta guarendo"], "a": 1, "sec": ["7"]}, {"id": "14-1", "ch": 14, "n": 1, "stem": "In quale scenario si deve sospettare la malaria?", "opts": ["Paziente afebbrile con rash isolato e nessun viaggio", "Tosse cronica con parametri vitali normali", "Febbre (≥37,5 °C) con residenza o viaggio in un'area endemica", "Disuria senza sintomi sistemici"], "a": 2, "sec": ["5.1"]}, {"id": "14-2", "ch": 14, "n": 2, "stem": "Il periodo di incubazione tipico di <em>P. falciparum</em> è:", "opts": ["12-14 giorni (intervallo 7-30 giorni)", "1-3 giorni", "2-6 mesi", "2-5 anni"], "a": 0, "sec": ["4"]}, {"id": "14-3", "ch": 14, "n": 3, "stem": "La malaria recidivante settimane o mesi dopo l'esposizione è associata soprattutto a:", "opts": ["Solo <em>P. falciparum</em>", "<em>P. malariae</em> per le cisti", "<em>Babesia</em> per le spore", "<em>P. vivax</em> o <em>P. ovale</em> per gli ipnozoiti"], "a": 3, "sec": ["1", "4"]}, {"id": "14-4", "ch": 14, "n": 4, "stem": "Lo strumento diagnostico standard per la malaria è:", "opts": ["La ricerca di antigeni urinari", "La microscopia ottica di strisci di sangue colorati", "La radiografia del torace", "L'esame parassitologico delle feci"], "a": 1, "sec": ["5.2"]}, {"id": "14-5", "ch": 14, "n": 5, "stem": "Un vantaggio chiave della microscopia rispetto agli RDT è:", "opts": ["L'identificazione di specie e la quantificazione della parassitemia", "Risultati più rapidi in 5 minuti", "Nessuna formazione necessaria", "Migliore rilevazione delle parassitemie molto basse rispetto alla PCR"], "a": 0, "sec": ["5.2"]}, {"id": "14-6", "ch": 14, "n": 6, "stem": "Un limite chiave della microscopia è:", "opts": ["Non può identificare la specie", "Fornisce solo risultati qualitativi", "Non richiede competenza", "Non può rilevare in modo affidabile parassitemie molto basse (&lt;5-10 parassiti/µl)"], "a": 3, "sec": ["5.2"]}, {"id": "14-7", "ch": 14, "n": 7, "stem": "Gli RDT sono particolarmente utili perché:", "opts": ["Quantificano con precisione la densità parassitaria", "Forniscono risultati in 15-20 minuti e sono facili da usare", "Richiedono un'infrastruttura di laboratorio avanzata", "Sostituiscono la microscopia in tutti i contesti"], "a": 1, "sec": ["5.3"]}, {"id": "14-8", "ch": 14, "n": 8, "stem": "In genere gli RDT non possono:", "opts": ["Rilevare antigeni malarici", "Essere usati senza elettricità", "Fornire una densità parassitaria quantitativa", "Essere usati in contesti a risorse limitate"], "a": 2, "sec": ["5.3"]}, {"id": "14-9", "ch": 14, "n": 9, "stem": "Occorre evitare di affidarsi agli RDT basati su HRP2 dove sono prevalenti le delezioni di <em>pfhrp2/3</em>, tra cui:", "opts": ["Amazzonia peruviana ed Eritrea", "Islanda e Groenlandia", "Giappone e Corea", "Canada e Stati Uniti"], "a": 0, "sec": ["5.3"]}, {"id": "14-10", "ch": 14, "n": 10, "stem": "Se il test iniziale per malaria è negativo ma il sospetto persiste, i test di controllo vanno eseguiti:", "opts": ["Una volta alla settimana per 4 settimane", "Solo se la febbre supera i 40 °C", "Solo dopo il fallimento degli antibiotici", "Ogni giorno per altri due giorni"], "a": 3, "sec": ["5.1"]}, {"id": "14-11", "ch": 14, "n": 11, "stem": "La malaria grave è meglio definita come:", "opts": ["Qualsiasi malaria con febbre", "Malaria con rash", "Malaria acuta con disfunzione d'organo maggiore e/o parassitemia elevata", "Malaria con sola piastrinopenia isolata"], "a": 2, "sec": ["4.2"]}, {"id": "14-12", "ch": 14, "n": 12, "stem": "Quale delle seguenti è una manifestazione di malaria grave?", "opts": ["Otite media", "Ipoglicemia", "Stipsi isolata", "Rinite allergica"], "a": 1, "sec": ["4.2"]}, {"id": "14-13", "ch": 14, "n": 13, "stem": "Quale delle seguenti è una manifestazione di malaria grave?", "opts": ["Insufficienza renale ed emoglobinuria (\"febbre emoglobinurica\")", "Solo cefalea lieve", "Congiuntivite isolata", "Cellulite localizzata"], "a": 0, "sec": ["4.2"]}, {"id": "14-14", "ch": 14, "n": 14, "stem": "Rispetto ai bambini, gli adulti con malaria grave presentano più spesso:", "opts": ["Convulsioni e anemia grave", "Solo esiti sul neurosviluppo", "Solo ipoglicemia", "Iperparassitemia, ARDS e ittero"], "a": 3, "sec": ["4.2"]}, {"id": "14-15", "ch": 14, "n": 15, "stem": "Nella malaria non complicata da <em>P. falciparum</em>, l'approccio terapeutico suggerito è:", "opts": ["Monoterapia con una singola artemisinina", "Nessun trattamento se afebbrile", "Terapia combinata a base di artemisinina (ACT)", "Soli antibiotici"], "a": 2, "sec": ["6.1"]}, {"id": "14-16", "ch": 14, "n": 16, "stem": "Se la malaria compare mentre il paziente assume la profilassi, il trattamento deve:", "opts": ["Usare lo stesso farmaco della profilassi", "Usare un farmaco diverso per il trattamento", "Essere rimandato finché gli strisci ripetuti non risultano positivi per 7 giorni", "Essere evitato per prevenire le resistenze"], "a": 1, "sec": ["6.1"]}, {"id": "14-17", "ch": 14, "n": 17, "stem": "Con una terapia appropriata della malaria non complicata, la parassitemia tipicamente si negativizza entro:", "opts": ["48-72 ore", "6-12 ore", "2-3 settimane", "2-3 mesi"], "a": 0, "sec": ["6.1", "7"]}, {"id": "14-18", "ch": 14, "n": 18, "stem": "Il trattamento iniziale della malaria grave consiste in:", "opts": ["Sola terapia orale", "Nessuna terapia antimalarica fino alla conferma di specie con PCR", "Soli antipiretici", "Terapia parenterale"], "a": 3, "sec": ["6.2"]}, {"id": "14-19", "ch": 14, "n": 19, "stem": "Nelle aree senza resistenza all'artemisinina, la terapia parenterale preferita (quando disponibile di qualità affidabile) è:", "opts": ["Chinino e.v. anziché artesunato", "Artesunato e.v. anziché chinino e.v.", "Sola ACT orale", "Sola clorochina"], "a": 1, "sec": ["6.2"]}, {"id": "14-20", "ch": 14, "n": 20, "stem": "Per i viaggiatori a rischio di infezione malarica, quale affermazione è più accurata?", "opts": ["La chemioprofilassi non è mai indicata", "Contano solo le zanzariere; i repellenti no", "La chemioprofilassi è raccomandata, e i viaggiatori devono richiedere una valutazione in caso di febbre durante o dopo il viaggio anche se hanno assunto la profilassi", "La febbre dopo un viaggio esclude la malaria se è stata assunta la profilassi"], "a": 2, "sec": ["8.2"]}, {"id": "15-1", "ch": 15, "n": 1, "stem": "Quali herpesvirus stabiliscono la latenza nei gangli sensitivi?", "opts": ["HSV-1, HSV-2 e VZV", "EBV e HHV-8", "CMV e HHV-6", "HHV-6 e HHV-7"], "a": 0, "sec": ["1.2"]}, {"id": "15-2", "ch": 15, "n": 2, "stem": "Cellule ingrandite con inclusioni intranucleari \"a occhio di gufo\" in una biopsia sono tipiche di:", "opts": ["EBV", "HSV-1", "CMV", "HHV-8"], "a": 2, "sec": ["1.2"]}, {"id": "15-3", "ch": 15, "n": 3, "stem": "Quale farmaco antivirale è il trattamento di prima linea delle infezioni da HSV e VZV?", "opts": ["Ganciclovir", "Aciclovir (o valaciclovir)", "Oseltamivir", "Ribavirina"], "a": 1, "sec": ["6.1"]}, {"id": "15-4", "ch": 15, "n": 4, "stem": "Un uomo di 58 anni presenta febbre, confusione e afasia. La RM mostra un'iperintensità temporale sinistra. La PCR per HSV sul liquor, prelevato al 2° giorno di sintomi, è negativa. Il passo successivo migliore è:", "opts": ["Sospendere aciclovir, perché la PCR è negativa", "Somministrare solo corticosteroidi", "Richiedere un pannello PCR multiplex sul liquor al posto della PCR specifica", "Proseguire aciclovir e.v. e ripetere la puntura lombare entro 3-7 giorni"], "a": 3, "sec": ["5.2", "6.2"]}, {"id": "15-5", "ch": 15, "n": 5, "stem": "Secondo le linee guida attuali, la sierologia tipo-specifica per HSV-2:", "opts": ["Deve essere usata per lo screening della popolazione generale", "Deve essere confermata con un secondo test quando il risultato è debolmente positivo", "Si esegue preferibilmente ricercando le IgM", "È sostituita dal test di Tzanck"], "a": 1, "sec": ["5.2"]}, {"id": "15-6", "ch": 15, "n": 6, "stem": "Il rischio di herpes neonatale è massimo quando la madre ha:", "opts": ["Un'infezione genitale primaria da HSV in prossimità del parto", "Un'anamnesi di herpes genitale ricorrente e nessuna lesione al parto", "Herpes labiale ricorrente", "IgG anti-HSV-1 acquisite nell'infanzia"], "a": 0, "sec": ["3.2"]}, {"id": "15-7", "ch": 15, "n": 7, "stem": "In un paziente con zoster della prima branca del nervo trigemino, le vescicole sulla punta del naso (segno di Hutchinson) indicano:", "opts": ["Sovrainfezione batterica", "Sindrome di Ramsay Hunt", "Un basso rischio di complicanze", "Coinvolgimento del nervo nasociliare e un aumentato rischio di coinvolgimento oculare"], "a": 3, "sec": ["4.2"]}, {"id": "15-8", "ch": 15, "n": 8, "stem": "Una paralisi facciale con vescicole nel condotto uditivo esterno suggerisce una riattivazione del VZV nel:", "opts": ["Ganglio trigeminale", "Gangli delle radici dorsali toraciche", "Ganglio genicolato", "Gangli sacrali"], "a": 2, "sec": ["4.2"]}, {"id": "15-9", "ch": 15, "n": 9, "stem": "In un paziente con herpes zoster, quale comorbidità richiede più spesso un adeguamento della terapia antivirale con aciclovir o valaciclovir?", "opts": ["Malattia renale cronica", "Ipertensione arteriosa", "Ipotiroidismo", "Artrosi"], "a": 0, "sec": ["6.1"]}, {"id": "15-10", "ch": 15, "n": 10, "stem": "Un neonato ha il rischio massimo di varicella neonatale grave quando l'eruzione varicellosa materna inizia:", "opts": ["Nel primo trimestre", "A 20 settimane di gestazione", "Un mese prima del parto", "Da 5 giorni prima a 2 giorni dopo il parto"], "a": 3, "sec": ["4.2", "8.2"]}, {"id": "15-11", "ch": 15, "n": 11, "stem": "Un test per anticorpi eterofili falsamente negativo nella mononucleosi da EBV è più probabile:", "opts": ["Negli adolescenti alla terza settimana di malattia", "Negli adulti con splenomegalia", "Nei bambini sotto i 4 anni e nelle fasi precoci della malattia", "Nei pazienti con linfocitosi atipica"], "a": 2, "sec": ["5.2"]}, {"id": "15-12", "ch": 15, "n": 12, "stem": "La sierologia per EBV mostra VCA IgM positive, VCA IgG positive, EBNA IgG negative. Ciò indica:", "opts": ["Nessuna precedente infezione da EBV", "Infezione primaria acuta da EBV", "Infezione pregressa da EBV", "Malattia cronica attiva da EBV, per definizione"], "a": 1, "sec": ["5.3"]}, {"id": "15-13", "ch": 15, "n": 13, "stem": "Un diciannovenne con mononucleosi trattato con amoxicillina sviluppa un'eruzione maculopapulare. L'affermazione corretta è:", "opts": ["Il paziente ha un'allergia alla penicillina confermata e permanente", "L'eruzione dimostra una coinfezione batterica", "È indicato l'aciclovir", "Questa eruzione è frequente nella mononucleosi e di solito non indica una vera allergia alla penicillina"], "a": 3, "sec": ["4.3"]}, {"id": "15-14", "ch": 15, "n": 14, "stem": "Nel trapianto di organo solido, il rischio massimo di malattia da CMV si ha con:", "opts": ["Donatore sieropositivo, ricevente sieronegativo (D+/R−)", "Donatore sieronegativo, ricevente sieronegativo (D−/R−)", "Donatore sieronegativo, ricevente sieropositivo (D−/R+)", "Il rischio non dipende dallo stato sierologico"], "a": 0, "sec": ["2.2"]}, {"id": "15-15", "ch": 15, "n": 15, "stem": "Quale farmaco è il trattamento di prima linea della malattia da CMV nei pazienti trapiantati?", "opts": ["Aciclovir", "Ganciclovir (e.v.) o valganciclovir (orale)", "Oseltamivir", "Fluconazolo"], "a": 1, "sec": ["6.5"]}, {"id": "15-16", "ch": 15, "n": 16, "stem": "Il principale effetto avverso da monitorare durante il trattamento con ganciclovir o valganciclovir è:", "opts": ["Epatotossicità", "Allungamento del QT", "Neutropenia (mielodepressione)", "Ototossicità"], "a": 2, "sec": ["6.1"]}, {"id": "15-17", "ch": 15, "n": 17, "stem": "L'infezione congenita da CMV nel neonato si diagnostica al meglio con:", "opts": ["PCR per CMV su urine o saliva entro i primi 21 giorni di vita", "IgG anti-CMV nel siero del neonato", "Avidità delle IgG anti-CMV nel neonato", "PCR per CMV sulle urine a 3 mesi di età"], "a": 0, "sec": ["5.2"]}, {"id": "15-18", "ch": 15, "n": 18, "stem": "L'HHV-8 è associato a:", "opts": ["Linfoma di Burkitt e carcinoma nasofaringeo", "Esantema critico", "Pitiriasi rosea", "Sarcoma di Kaposi, linfoma primitivo delle sierose e malattia di Castleman multicentrica"], "a": 3, "sec": ["4.5"]}, {"id": "15-19", "ch": 15, "n": 19, "stem": "L'esantema critico (roseola infantum) è caratterizzato da:", "opts": ["Un'eruzione vescicolare in diversi stadi evolutivi", "Febbre alta per 3-5 giorni, poi un'eruzione allo sfebbramento", "Un'eruzione \"a schiaffo\"", "Eruzione e febbre che iniziano insieme, con congiuntivite e macchie di Koplik"], "a": 1, "sec": ["4.5"]}, {"id": "15-20", "ch": 15, "n": 20, "stem": "Il vaccino ricombinante anti-zoster:", "opts": ["È un vaccino vivo attenuato controindicato nei pazienti immunocompromessi", "È una dose singola somministrata a 50 anni", "È un vaccino non vivo adiuvato a base di glicoproteina E, in due dosi, utilizzabile negli adulti immunocompromessi", "Non deve essere somministrato a chi ha già avuto lo zoster"], "a": 2, "sec": ["8.1"]}, {"id": "16-1", "ch": 16, "n": 1, "stem": "Quale virus epatitico ha un genoma a DNA?", "opts": ["HAV", "HBV", "HCV", "HEV"], "a": 1, "sec": ["1.1"]}, {"id": "16-2", "ch": 16, "n": 2, "stem": "L'HDV può infettare gli epatociti solo in presenza dell'HBV perché necessita:", "opts": ["Del capside dell'HAV", "Della proteina core dell'HCV", "Della proteina NS5A dell'HBV", "Della proteina dell'envelope dell'HBV (HBsAg)"], "a": 3, "sec": ["1.3"]}, {"id": "16-3", "ch": 16, "n": 3, "stem": "Il rischio di sviluppare un'infezione cronica da HBV è massimo quando l'infezione è acquisita:", "opts": ["In epoca perinatale", "Nell'adolescenza", "In età adulta per contatto sessuale", "In età adulta per puntura d'ago accidentale"], "a": 0, "sec": ["2.3"]}, {"id": "16-4", "ch": 16, "n": 4, "stem": "In Europa, la principale fonte di infezione autoctona da HEV è:", "opts": ["Acqua potabile contaminata dopo le alluvioni monsoniche", "La trasmissione sessuale", "Carne di maiale, cinghiale o selvaggina poco cotta", "Le punture di zanzara"], "a": 2, "sec": ["2.2"]}, {"id": "16-5", "ch": 16, "n": 5, "stem": "L'infezione acuta da HEV comporta il rischio di morte più elevato in:", "opts": ["Bambini sotto i 5 anni", "Giovani uomini sani", "Donne in gravidanza nel terzo trimestre", "Viaggiatori vaccinati"], "a": 2, "sec": ["3.6"]}, {"id": "16-6", "ch": 16, "n": 6, "stem": "Dopo un'infezione acuta da HCV, la proporzione di adulti che sviluppa un'infezione cronica è:", "opts": ["La maggioranza (circa il 70-75%)", "Meno del 5%", "Circa il 10%", "Il 100%"], "a": 0, "sec": ["3.5"]}, {"id": "16-7", "ch": 16, "n": 7, "stem": "Un paziente ha HBsAg positivo, IgM anti-HBc positive e anti-HBs negativo. La diagnosi più probabile è:", "opts": ["Infezione cronica da HBV in fase HBeAg-negativa", "Immunità da vaccinazione", "Infezione pregressa risolta", "Epatite B acuta"], "a": 3, "sec": ["5.3"]}, {"id": "16-8", "ch": 16, "n": 8, "stem": "Uno studente di area sanitaria ha anti-HBs positivo, con HBsAg e anti-HBc negativi. Questo profilo indica:", "opts": ["Infezione acuta da HBV", "Immunità da vaccinazione", "Infezione occulta da HBV", "Periodo finestra dell'HBV acuta"], "a": 1, "sec": ["5.3"]}, {"id": "16-9", "ch": 16, "n": 9, "stem": "Un paziente è anti-HCV positivo e HCV-RNA negativo in due occasioni. L'interpretazione più probabile è:", "opts": ["Infezione da HCV risolta (o anticorpo falsamente positivo)", "Epatite C cronica attiva", "HCV acuta nel periodo finestra", "Immunità protettiva contro la reinfezione"], "a": 0, "sec": ["5.4"]}, {"id": "16-10", "ch": 16, "n": 10, "stem": "L'epatite A acuta si diagnostica con:", "opts": ["IgG anti-HAV", "Biopsia epatica", "IgM anti-HAV", "Genotipizzazione dell'HAV"], "a": 2, "sec": ["5.2"]}, {"id": "16-11", "ch": 16, "n": 11, "stem": "Un trapiantato di rene ha ALT persistentemente aumentate. L'esame migliore per diagnosticare un'epatite E cronica è:", "opts": ["Le sole IgM anti-HEV", "L'HEV-RNA mediante test di amplificazione degli acidi nucleici", "Le sole IgG anti-HEV", "Ripetere le ALT dopo 6 mesi"], "a": 1, "sec": ["5.6"]}, {"id": "16-12", "ch": 16, "n": 12, "stem": "Gli analoghi nucleos(t)idici di prima linea per l'epatite B cronica sono:", "opts": ["Lamivudina", "Adefovir", "Telbivudina", "Entecavir, tenofovir disoproxil o tenofovir alafenamide"], "a": 3, "sec": ["6.2"]}, {"id": "16-13", "ch": 16, "n": 13, "stem": "Quale affermazione sull'attuale trattamento dell'epatite C cronica è corretta?", "opts": ["L'interferone fa ancora parte della terapia di prima linea", "Il trattamento deve essere proseguito per tutta la vita per mantenere il virus soppresso", "Il trattamento è riservato ai pazienti con cirrosi", "Cicli brevi (8-12 settimane) di DAA orali guariscono più del 95% dei pazienti"], "a": 3, "sec": ["6.4"]}, {"id": "16-14", "ch": 16, "n": 14, "stem": "La guarigione dall'epatite C è definita come:", "opts": ["HCV-RNA non rilevabile 12 settimane dopo la fine del trattamento (SVR12)", "Scomparsa degli anticorpi anti-HCV", "ALT normali alla fine del trattamento", "HCV-RNA non rilevabile alla settimana 4 di trattamento"], "a": 0, "sec": ["6.4"]}, {"id": "16-15", "ch": 16, "n": 15, "stem": "Quali pazienti devono essere testati per l'epatite D (anti-HDV)?", "opts": ["Solo i pazienti con epatite B acuta", "Solo i pazienti con cirrosi", "Tutti i pazienti HBsAg-positivi", "Solo le persone che si iniettano droghe"], "a": 2, "sec": ["5.5"]}, {"id": "16-16", "ch": 16, "n": 16, "stem": "Un paziente HBsAg negativo e anti-HBc positivo sta per iniziare rituximab. L'approccio corretto è:", "opts": ["Nessun intervento, perché l'HBsAg è negativo", "Profilassi antivirale con entecavir o tenofovir", "Solo vaccinazione anti-HBV", "Interferone peghilato per 48 settimane"], "a": 1, "sec": ["6.2"]}, {"id": "16-17", "ch": 16, "n": 17, "stem": "Dopo il trattamento efficace dell'epatite C (SVR12), quale affermazione è corretta?", "opts": ["Gli anticorpi anti-HCV si negativizzano", "Il paziente è protetto dalla reinfezione", "I pazienti con cirrosi restano a rischio di tumore del fegato e necessitano di sorveglianza continua", "La terapia antivirale deve essere proseguita per tutta la vita"], "a": 2, "sec": ["7.3"]}, {"id": "16-18", "ch": 16, "n": 18, "stem": "Il neonato di una madre HBsAg-positiva deve ricevere:", "opts": ["Il vaccino anti-HBV solo a 2 mesi", "Le sole HBIG, senza vaccino", "Tenofovir per 6 mesi", "Vaccino anti-HBV più HBIG entro 12-24 ore dalla nascita"], "a": 3, "sec": ["8.2"]}, {"id": "16-19", "ch": 16, "n": 19, "stem": "Un trentenne sano è stato esposto 5 giorni fa a un convivente con epatite A acuta. La profilassi post-esposizione raccomandata è:", "opts": ["Una dose di vaccino anti-epatite A", "Ribavirina", "Nessuna profilassi", "Immunoglobuline anti-epatite B"], "a": 0, "sec": ["8.1"]}, {"id": "16-20", "ch": 16, "n": 20, "stem": "Per quale virus epatitico non è disponibile un vaccino?", "opts": ["HAV", "HCV", "HBV", "HEV in Cina"], "a": 1, "sec": ["8.3"]}, {"id": "17-1", "ch": 17, "n": 1, "stem": "Quale enzima dell'HIV converte il genoma virale a RNA in DNA?", "opts": ["Trascrittasi inversa", "Integrasi", "Proteasi", "RNA polimerasi RNA-dipendente"], "a": 0, "sec": ["1.1–1.2"]}, {"id": "17-2", "ch": 17, "n": 2, "stem": "Le persone omozigoti per la delezione CCR5-Δ32 sono in gran parte resistenti all'infezione da:", "opts": ["Virus dell'epatite B", "HIV-1 a tropismo CXCR4", "HIV-1 a tropismo CCR5", "Tutti i retrovirus"], "a": 2, "sec": ["3.1"]}, {"id": "17-3", "ch": 17, "n": 3, "stem": "Senza trattamento, il tempo mediano dall'infezione da HIV all'AIDS è di circa:", "opts": ["6 mesi", "10 anni", "2 anni", "25 anni"], "a": 1, "sec": ["3.2"]}, {"id": "17-4", "ch": 17, "n": 4, "stem": "Quale via comporta il rischio più elevato di trasmissione dell'HIV per singolo atto?", "opts": ["Rapporto vaginale recettivo", "Puntura d'ago professionale", "Rapporto anale insertivo", "Rapporto anale recettivo"], "a": 3, "sec": ["2.3"]}, {"id": "17-5", "ch": 17, "n": 5, "stem": "In Italia, circa quale proporzione delle nuove diagnosi di HIV aveva una conta dei CD4 inferiore a 350 cellule/µl?", "opts": ["Circa il 10%", "Circa il 25%", "Circa il 60%", "Circa il 90%"], "a": 2, "sec": ["2.2"]}, {"id": "17-6", "ch": 17, "n": 6, "stem": "La deplezione massiva dei linfociti T CD4+ durante l'infezione acuta da HIV avviene principalmente:", "opts": ["Nel tessuto linfoide associato all'intestino", "Nel midollo osseo", "Nel timo", "Solo nel sangue periferico"], "a": 0, "sec": ["3.2"]}, {"id": "17-7", "ch": 17, "n": 7, "stem": "La ART deve essere proseguita per tutta la vita principalmente perché:", "opts": ["La conta dei CD4 non si ricostituisce mai", "Tutti i farmaci antiretrovirali sono virucidi solo ad alte dosi", "Entro un anno si sviluppa resistenza a tutte le classi di farmaci", "Il provirus integrato nei linfociti T CD4+ della memoria quiescenti non viene eliminato dalla ART"], "a": 3, "sec": ["3.4"]}, {"id": "17-8", "ch": 17, "n": 8, "stem": "Un uomo di 24 anni presenta febbre, faringite, rash maculopapulare, ulcere orali e linfoadenopatia due settimane dopo un rapporto senza preservativo. Un test anticorpale rapido è negativo. Il passo successivo migliore è:", "opts": ["Rassicurarlo; il test negativo esclude l'HIV", "Richiedere un test combinato Ag/Ab di 4ª generazione e l'HIV-1 RNA", "Ripetere il test anticorpale tra 6 mesi", "Richiedere un Western blot"], "a": 1, "sec": ["4.1", "5.2"]}, {"id": "17-9", "ch": 17, "n": 9, "stem": "Nell'algoritmo diagnostico di laboratorio raccomandato, un test combinato Ag/Ab di 4ª generazione reattivo seguito da un test di differenziazione anticorpale negativo deve essere seguito da:", "opts": ["Un Western blot", "HIV-1 RNA (test di amplificazione degli acidi nucleici)", "Una conta dei CD4", "Un test di screening ripetuto dopo 1 anno"], "a": 1, "sec": ["5.3"]}, {"id": "17-10", "ch": 17, "n": 10, "stem": "Quale esame NON fa parte della valutazione iniziale di un paziente con nuova diagnosi di HIV?", "opts": ["Conta dei CD4", "HIV RNA (carica virale)", "RM encefalo di routine", "Sierologia per epatite B e C"], "a": 2, "sec": ["5.4"]}, {"id": "17-11", "ch": 17, "n": 11, "stem": "Un paziente con HIV presenta da 3 settimane tosse secca, dispnea da sforzo, desaturazione da sforzo, LDH aumentata e infiltrati bilaterali a vetro smerigliato. La conta dei CD4 è 90 cellule/µl. La diagnosi più probabile è:", "opts": ["Polmonite da <em>Pneumocystis jirovecii</em>", "Polmonite lobare pneumococcica", "Sarcoma di Kaposi polmonare", "Polmonite da CMV"], "a": 0, "sec": ["4.3"]}, {"id": "17-12", "ch": 17, "n": 12, "stem": "Quale infezione opportunistica si presenta tipicamente con CD4 inferiori a 50 cellule/µl?", "opts": ["Candidosi orale", "Herpes zoster", "Tubercolosi polmonare", "Retinite da CMV"], "a": 3, "sec": ["4.3"]}, {"id": "17-13", "ch": 17, "n": 13, "stem": "Secondo le linee guida attuali, la ART deve essere iniziata:", "opts": ["Solo quando i CD4 scendono sotto 350 cellule/µl", "Solo nei pazienti con una malattia indicativa di AIDS", "Solo dopo la disponibilità dei risultati del test di resistenza", "In tutte le persone con HIV, il prima possibile, indipendentemente dalla conta dei CD4"], "a": 3, "sec": ["6.1"]}, {"id": "17-14", "ch": 17, "n": 14, "stem": "In un paziente con nuova diagnosi di HIV e meningite criptococcica, la ART deve essere:", "opts": ["Iniziata lo stesso giorno della terapia antifungina", "Posticipata di circa 4-6 settimane dall'inizio della terapia antifungina", "Posticipata finché la conta dei CD4 supera 500 cellule/µl", "Mai iniziata"], "a": 1, "sec": ["6.1"]}, {"id": "17-15", "ch": 17, "n": 15, "stem": "In un paziente con HIV ed epatite B cronica, quale regime NON è appropriato?", "opts": ["Dolutegravir/lamivudina (regime duplice)", "Bictegravir/TAF/FTC", "Dolutegravir + TDF + FTC", "Dolutegravir + TAF + FTC"], "a": 0, "sec": ["6.3"]}, {"id": "17-16", "ch": 17, "n": 16, "stem": "Per la maggior parte delle persone che iniziano la ART, il regime preferito è:", "opts": ["Un singolo inibitore della proteasi", "Due NRTI senza un terzo farmaco", "Un inibitore dell'integrasi più uno o due NRTI", "Un singolo NNRTI"], "a": 2, "sec": ["6.3"]}, {"id": "17-17", "ch": 17, "n": 17, "stem": "Tre settimane dopo l'inizio della ART, un paziente in trattamento per TB sviluppa nuova febbre e linfonodi in aumento di volume mentre la carica virale è in calo. La spiegazione più probabile è:", "opts": ["Fallimento virologico", "HIV farmacoresistente", "Sindrome infiammatoria da immunoricostituzione", "Reinfezione acuta da HIV"], "a": 2, "sec": ["6.4"]}, {"id": "17-18", "ch": 17, "n": 18, "stem": "La profilassi primaria con cotrimossazolo è indicata quando la conta dei CD4 è inferiore a:", "opts": ["500 cellule/µl", "350 cellule/µl", "50 cellule/µl", "200 cellule/µl"], "a": 3, "sec": ["6.5"]}, {"id": "17-19", "ch": 17, "n": 19, "stem": "La profilassi post-esposizione (PEP) per l'HIV deve essere iniziata:", "opts": ["Il prima possibile e non oltre 72 ore dall'esposizione, per 28 giorni", "Entro 7 giorni dall'esposizione, per 14 giorni", "Solo dopo la disponibilità del test HIV della fonte", "Entro 72 ore, per 3 mesi"], "a": 0, "sec": ["8.3"]}, {"id": "17-20", "ch": 17, "n": 20, "stem": "Quale affermazione sulla prevenzione dell'HIV è corretta?", "opts": ["È disponibile un vaccino autorizzato contro l'HIV per i gruppi ad alto rischio", "Una persona con carica virale stabilmente non rilevabile non trasmette l'HIV per via sessuale", "I vaccini vivi sono sicuri con qualsiasi conta dei CD4", "La PrEP orale al bisogno è raccomandata per l'esposizione vaginale"], "a": 1, "sec": ["8.1"]}, {"id": "18-1", "ch": 18, "n": 1, "stem": "Un uomo di 28 anni presenta un'unica ulcera indolore e indurita sul pene con linfonodi inguinali duri e non dolenti. La causa più probabile è:", "opts": ["Herpes genitale", "Sifilide primaria", "Ulcera molle", "Mpox"], "a": 1, "sec": ["4.2", "4.7"]}, {"id": "18-2", "ch": 18, "n": 2, "stem": "Quale microrganismo è privo di parete cellulare ed è quindi intrinsecamente resistente ai β-lattamici?", "opts": ["<em>Neisseria gonorrhoeae</em>", "<em>Treponema pallidum</em>", "<em>Chlamydia trachomatis</em>", "<em>Mycoplasma genitalium</em>"], "a": 3, "sec": ["1"]}, {"id": "18-3", "ch": 18, "n": 3, "stem": "La IST curabile più comune al mondo è:", "opts": ["Tricomoniasi", "Clamidia", "Gonorrea", "Sifilide"], "a": 0, "sec": ["2"]}, {"id": "18-4", "ch": 18, "n": 4, "stem": "Un esantema che interessa palmi e piante, placche mucose e linfoadenopatia generalizzata suggeriscono:", "opts": ["Sifilide primaria", "Sifilide latente tardiva", "Sifilide secondaria", "Sifilide terziaria"], "a": 2, "sec": ["4.2"]}, {"id": "18-5", "ch": 18, "n": 5, "stem": "Quale affermazione sulla neurosifilide è corretta?", "opts": ["Compare solo decenni dopo l'infezione", "Un VDRL liquorale negativo la esclude", "Può comparire in qualsiasi stadio della sifilide", "Si tratta con una singola dose di penicillina benzatina"], "a": 2, "sec": ["3.1", "5.4"]}, {"id": "18-6", "ch": 18, "n": 6, "stem": "Il test diagnostico di scelta per clamidia e gonorrea è:", "opts": ["Test di amplificazione degli acidi nucleici (NAAT)", "Sierologia", "Colorazione di Gram di un tampone vaginale", "Emocoltura"], "a": 0, "sec": ["5.2"]}, {"id": "18-7", "ch": 18, "n": 7, "stem": "Un MSM in PrEP per l'HIV si presenta per lo screening di routine ed è asintomatico. Quale approccio è corretto?", "opts": ["Solo NAAT sulle urine", "Nessun test perché è asintomatico", "Solo sierologia per la sifilide", "NAAT su sedi genitale, rettale e faringea, più sierologia per sifilide e HIV"], "a": 3, "sec": ["5.1"]}, {"id": "18-8", "ch": 18, "n": 8, "stem": "Quale test si usa per monitorare la risposta alla terapia della sifilide?", "opts": ["TPPA", "RPR o VDRL quantitativo", "FTA-ABS", "EIA treponemico"], "a": 1, "sec": ["5.3", "7.2"]}, {"id": "18-9", "ch": 18, "n": 9, "stem": "Una donna con sifilide secondaria e titoli anticorpali molto elevati ha un RPR non diluito negativo. La spiegazione più probabile è:", "opts": ["Effetto prozona", "Infezione guarita", "Test treponemico falsamente positivo", "Coinfezione da HIV che invalida la sierologia"], "a": 0, "sec": ["5.3"]}, {"id": "18-10", "ch": 18, "n": 10, "stem": "Quale presentazione di sifilide viene trattata come neurosifilide?", "opts": ["Sifiloma primario", "Sifilide latente precoce", "Sifilide oculare", "Condilomi piani"], "a": 2, "sec": ["5.4"]}, {"id": "18-11", "ch": 18, "n": 11, "stem": "La terapia raccomandata per la gonorrea non complicata si basa su:", "opts": ["Ciprofloxacina", "Ceftriaxone", "Sola doxiciclina", "Amoxicillina"], "a": 1, "sec": ["6.2"]}, {"id": "18-12", "ch": 18, "n": 12, "stem": "Per la clamidia urogenitale e rettale non complicata in un adulto non in gravidanza, la terapia preferita è:", "opts": ["Azitromicina in dose singola", "Ceftriaxone", "Metronidazolo", "Doxiciclina per 7 giorni"], "a": 3, "sec": ["6.3"]}, {"id": "18-13", "ch": 18, "n": 13, "stem": "Una donna in gravidanza con sifilide precoce riferisce un'allergia alla penicillina. La gestione corretta è:", "opts": ["Azitromicina", "Doxiciclina", "Nessuna terapia fino al parto", "Desensibilizzazione alla penicillina, poi penicillina"], "a": 3, "sec": ["6.4"]}, {"id": "18-14", "ch": 18, "n": 14, "stem": "Febbre, cefalea e mialgie compaiono 6 ore dopo la penicillina per una sifilide secondaria. Si tratta di:", "opts": ["Allergia alla penicillina, quindi cambiare farmaco", "Reazione di Jarisch-Herxheimer", "Fallimento terapeutico", "Neurosifilide"], "a": 1, "sec": ["6.4"]}, {"id": "18-15", "ch": 18, "n": 15, "stem": "Un MSM ha una proctite con secrezione ematica e un NAAT rettale positivo per clamidia. La terapia più appropriata è:", "opts": ["Azitromicina in dose singola", "Solo ceftriaxone", "Doxiciclina per 21 giorni (linfogranuloma venereo)", "Metronidazolo"], "a": 2, "sec": ["6.3"]}, {"id": "18-16", "ch": 18, "n": 16, "stem": "La terapia di <em>M. genitalium</em> deve essere guidata da:", "opts": ["Test per le mutazioni di resistenza ai macrolidi", "Colorazione di Gram", "Coltura su terreni di routine", "Sierologia"], "a": 0, "sec": ["5.2", "6.5"]}, {"id": "18-17", "ch": 18, "n": 17, "stem": "Dopo la terapia della sifilide precoce, una risposta sierologica adeguata è:", "opts": ["Un test treponemico negativo a 6 mesi", "Qualsiasi riduzione del titolo di RPR", "Una riduzione di quattro volte (due diluizioni) del titolo di RPR entro 6-12 mesi", "Un titolo di RPR stabile"], "a": 2, "sec": ["7.2"]}, {"id": "18-18", "ch": 18, "n": 18, "stem": "Un test di guarigione per la gonorrea è raccomandato di routine per:", "opts": ["Infezione uretrale nell'uomo", "Infezione cervicale", "Infezione rettale", "Infezione faringea"], "a": 3, "sec": ["7.1"]}, {"id": "18-19", "ch": 18, "n": 19, "stem": "La doxy-PEP deve essere offerta a:", "opts": ["MSM e donne transgender con una IST batterica negli ultimi 12 mesi", "Tutti gli adulti sessualmente attivi", "Donne cisgender che usano la contraccezione", "Chiunque inizi la PrEP per l'HIV, qualunque sia la storia di IST"], "a": 0, "sec": ["8.1"]}, {"id": "18-20", "ch": 18, "n": 20, "stem": "La profilassi post-esposizione con doxiciclina (doxy-PEP) è meno efficace contro:", "opts": ["Clamidia", "Gonorrea", "Sifilide", "È ugualmente efficace contro tutte e tre"], "a": 1, "sec": ["8.1"]}, {"id": "19-1", "ch": 19, "n": 1, "stem": "Quale reperto tissutale è più tipico di <em>Aspergillus</em>?", "opts": ["Ife larghe, nastriformi, scarsamente settate, ramificate ad angolo retto", "Ife sottili, regolarmente settate, con ramificazione ad angolo acuto (circa 45°)", "Lieviti gemmanti capsulati colorati con inchiostro di china", "Sferule contenenti endospore"], "a": 1, "sec": ["1.1"]}, {"id": "19-2", "ch": 19, "n": 2, "stem": "Come si acquisisce di solito l'infezione da <em>Aspergillus</em>?", "opts": ["Contatto interumano", "Ingestione di alimenti contaminati", "Attraverso cateteri intravascolari", "Inalazione di conidi aerodispersi dall'ambiente"], "a": 3, "sec": ["1.1"]}, {"id": "19-3", "ch": 19, "n": 3, "stem": "Quali pazienti hanno il rischio più elevato di aspergillosi polmonare invasiva?", "opts": ["Pazienti con neutropenia prolungata e profonda (ad es. leucemia acuta in chemioterapia)", "Giovani adulti sani dopo un'infezione virale delle alte vie respiratorie", "Donne in gravidanza", "Pazienti con diabete di tipo 2 ben controllato"], "a": 0, "sec": ["2.1"]}, {"id": "19-4", "ch": 19, "n": 4, "stem": "Quale cellula di difesa dell'ospite è principalmente responsabile dell'uccisione delle ife di <em>Aspergillus</em>?", "opts": ["Eosinofilo", "Linfocita B", "Neutrofilo", "Mastcellula"], "a": 2, "sec": ["3.1"]}, {"id": "19-5", "ch": 19, "n": 5, "stem": "Un paziente con LMA è neutropenico da 14 giorni ed è febbrile nonostante 5 giorni di antibiotici ad ampio spettro. La TC del torace mostra un nodulo circondato da un'opacità a vetro smerigliato. Si tratta:", "opts": ["Del segno della semiluna aerea, tipico del recupero dei neutrofili", "Del segno dell'alone invertito, tipico dell'IPA", "Del segno dell'alone, segno precoce di infezione fungina angioinvasiva", "Di un reperto che esclude un'infezione fungina"], "a": 2, "sec": ["5.1"]}, {"id": "19-6", "ch": 19, "n": 6, "stem": "Quale affermazione sul galattomannano è corretta?", "opts": ["Il galattomannano sul BAL è più sensibile di quello sierico, soprattutto nei pazienti non neutropenici", "È un marcatore specifico per le specie di <em>Candida</em>", "La sua sensibilità aumenta durante la profilassi attiva sulle muffe", "Fa parte della parete cellulare dei Mucorales"], "a": 0, "sec": ["5.1"]}, {"id": "19-7", "ch": 19, "n": 7, "stem": "Secondo le attuali definizioni di consenso, un paziente con un fattore dell'ospite e una lesione TC tipica, ma senza evidenza micologica, ha:", "opts": ["IPA accertata", "IPA probabile", "IPA esclusa", "IPA possibile"], "a": 3, "sec": ["5.1"]}, {"id": "19-8", "ch": 19, "n": 8, "stem": "Quale è un farmaco di prima linea raccomandato per l'aspergillosi polmonare invasiva?", "opts": ["Fluconazolo", "Isavuconazolo", "Caspofungin in monoterapia", "Flucitosina"], "a": 1, "sec": ["6.1"]}, {"id": "19-9", "ch": 19, "n": 9, "stem": "Il monitoraggio terapeutico dei livelli è particolarmente raccomandato per il voriconazolo perché:", "opts": ["La sua farmacocinetica è non lineare e molto variabile (ad es. polimorfismi del CYP2C19)", "È escreto immodificato nelle urine", "Non ha effetti avversi a nessuna concentrazione", "È disponibile solo in formulazione inalatoria"], "a": 0, "sec": ["6.1"]}, {"id": "19-10", "ch": 19, "n": 10, "stem": "Quali esami si usano per seguire la risposta alla terapia dell'aspergillosi polmonare invasiva?", "opts": ["Procalcitonina e proteina C reattiva", "Emocolture ripetute", "TC del torace e galattomannano sierico", "Colorazione di Gram dell'espettorato"], "a": 2, "sec": ["7.1"]}, {"id": "19-11", "ch": 19, "n": 11, "stem": "Quale fattore di rischio è più tipico dell'infezione del circolo ematico da <em>Candida parapsilosis</em>?", "opts": ["Inalazione di spore durante lavori edili", "Malattia granulomatosa cronica", "Asma con ABPA", "Catetere venoso centrale e nutrizione parenterale, con trasmissione tramite le mani degli operatori sanitari"], "a": 3, "sec": ["1.2", "3.2"]}, {"id": "19-12", "ch": 19, "n": 12, "stem": "Quale specie di <em>Candida</em> è intrinsecamente resistente al fluconazolo?", "opts": ["<em>C. albicans</em>", "<em>C. krusei</em> (<em>Pichia kudriavzevii</em>)", "<em>C. parapsilosis</em>", "<em>C. tropicalis</em>"], "a": 1, "sec": ["1.2"]}, {"id": "19-13", "ch": 19, "n": 13, "stem": "La sensibilità delle emocolture per tutte le forme di candidosi invasiva (compresa l'infezione profonda) è approssimativamente:", "opts": ["100%", "50%", "95%", "5%"], "a": 1, "sec": ["5.2"]}, {"id": "19-14", "ch": 19, "n": 14, "stem": "Quale affermazione sul β-D-glucano è corretta?", "opts": ["È specifico per <em>Aspergillus</em>", "Non è mai falsamente positivo", "È un marcatore panfungino con elevato valore predittivo negativo", "Rileva in modo affidabile i Mucorales"], "a": 2, "sec": ["5.1", "5.2"]}, {"id": "19-15", "ch": 19, "n": 15, "stem": "La terapia di prima linea della candidemia in un paziente critico non neutropenico è:", "opts": ["Un'echinocandina", "Il fluconazolo in tutti i casi", "Il voriconazolo in monoterapia", "Nessuna terapia fino all'identificazione di specie"], "a": 0, "sec": ["6.2"]}, {"id": "19-16", "ch": 19, "n": 16, "stem": "Il passaggio da un'echinocandina al fluconazolo orale nella candidemia è appropriato quando:", "opts": ["La prima emocoltura diventa positiva", "L'isolato è <em>C. krusei</em>", "Il paziente è ancora in shock settico", "Il paziente è clinicamente stabile, l'isolato è sensibile al fluconazolo e le emocolture ripetute sono negative"], "a": 3, "sec": ["6.2"]}, {"id": "19-17", "ch": 19, "n": 17, "stem": "La durata abituale della terapia nella candidemia non complicata è:", "opts": ["3 giorni dalla prima emocoltura positiva", "7 giorni dalla rimozione del catetere", "6 settimane in tutti i pazienti", "14 giorni dalla prima emocoltura negativa e dalla risoluzione dei sintomi"], "a": 3, "sec": ["6.2"]}, {"id": "19-18", "ch": 19, "n": 18, "stem": "Quale esame deve essere eseguito in ogni paziente con candidemia?", "opts": ["Esame del fondo oculare in midriasi", "Biopsia osteomidollare", "Puntura lombare", "Broncoscopia"], "a": 0, "sec": ["7.2"]}, {"id": "19-19", "ch": 19, "n": 19, "stem": "In un paziente con candidemia il cui catetere venoso centrale è la probabile fonte, l'approccio corretto è:", "opts": ["Lasciare il catetere in sede e trattare attraverso di esso", "Trattare con antifungini solo se la febbre persiste", "Rimuovere il catetere oltre alla terapia antifungina", "Sostituire il catetere su guida senza terapia antifungina"], "a": 2, "sec": ["6.2"]}, {"id": "19-20", "ch": 19, "n": 20, "stem": "La profilassi con posaconazolo è indicata principalmente in quale popolazione?", "opts": ["Tutti i pazienti di terapia intensiva in ventilazione meccanica", "Pazienti con LMA/SMD durante la chemioterapia di induzione e riceventi di HSCT allogenico con GVHD", "Viaggiatori sani diretti ai tropici", "Pazienti con candiduria asintomatica"], "a": 1, "sec": ["8.1"]}, {"id": "20-1", "ch": 20, "n": 1, "stem": "Quale zecca è il principale vettore della borreliosi di Lyme e dell'encefalite da zecche in Europa?", "opts": ["<em>Rhipicephalus sanguineus</em>", "<em>Ixodes ricinus</em>", "<em>Hyalomma marginatum</em>", "<em>Ornithodoros erraticus</em>"], "a": 1, "sec": ["1.1"]}, {"id": "20-2", "ch": 20, "n": 2, "stem": "L'acrodermatite cronica atrofica è associata principalmente a quale genospecie di <em>Borrelia</em>?", "opts": ["<em>B. garinii</em>", "<em>B. burgdorferi</em> sensu stricto", "<em>B. miyamotoi</em>", "<em>B. afzelii</em>"], "a": 3, "sec": ["1.2", "4.1"]}, {"id": "20-3", "ch": 20, "n": 3, "stem": "La febbre bottonosa del Mediterraneo è trasmessa principalmente da:", "opts": ["La zecca del cane, <em>Rhipicephalus sanguineus</em>", "La zecca \"lone star\", <em>Amblyomma americanum</em>", "I pidocchi del corpo", "Le zecche molli del genere <em>Ornithodoros</em>"], "a": 0, "sec": ["1.1", "2.2"]}, {"id": "20-4", "ch": 20, "n": 4, "stem": "Oltre che con le punture di zecca, l'encefalite da zecche può essere trasmessa con:", "opts": ["Le goccioline respiratorie dei pazienti infetti", "Le punture di zanzara", "Il latte non pastorizzato di capre, pecore o mucche infette", "L'acqua potabile contaminata"], "a": 2, "sec": ["2.7"]}, {"id": "20-5", "ch": 20, "n": 5, "stem": "Un escursionista di 35 anni si presenta con una chiazza eritematosa non pruriginosa di 8 cm in espansione sulla coscia, con schiarimento centrale, 10 giorni dopo una passeggiata nei boschi in Trentino. Qual è il passo successivo corretto?", "opts": ["Iniziare la doxiciclina orale senza test sierologici", "Richiedere la sierologia per Lyme a due livelli e attendere il risultato", "Eseguire una biopsia cutanea per la coltura", "Eseguire una puntura lombare"], "a": 0, "sec": ["5.2", "6.1"]}, {"id": "20-6", "ch": 20, "n": 6, "stem": "La sindrome di Bannwarth, tipica della neuroborreliosi europea, consiste in:", "opts": ["Encefalomielite cronica progressiva con paraparesi spastica", "Paralisi flaccida acuta di entrambi gli arti inferiori", "Meningoradicolite dolorosa, spesso con paralisi facciale e liquor linfocitario", "Neurite ottica bilaterale"], "a": 2, "sec": ["4.1"]}, {"id": "20-7", "ch": 20, "n": 7, "stem": "Quale affermazione sulla cardite di Lyme è corretta?", "opts": ["Di solito richiede l'impianto precoce di un pacemaker definitivo", "Causa tipicamente un blocco AV che può fluttuare rapidamente e di solito si risolve con gli antibiotici", "È la manifestazione più comune della malattia di Lyme tardiva", "Si tratta con cicli antibiotici prolungati di almeno 3 mesi"], "a": 1, "sec": ["4.1", "6.1"]}, {"id": "20-8", "ch": 20, "n": 8, "stem": "Quale quadro di laboratorio è più tipico dell'anaplasmosi granulocitica umana?", "opts": ["Neutrofilia, eosinofilia e transaminasi normali", "Anemia emolitica con schistociti", "Linfocitosi con linfociti atipici", "Leucopenia, piastrinopenia e aumento delle transaminasi"], "a": 3, "sec": ["4.3"]}, {"id": "20-9", "ch": 20, "n": 9, "stem": "Un bambino siciliano di 5 anni presenta febbre alta, esantema maculopapulare al tronco, ai palmi e alle piante, e un'escara nera dietro l'orecchio. Quale terapia è di prima linea?", "opts": ["Doxiciclina", "Amoxicillina-clavulanato", "Ciprofloxacina", "Ceftriaxone"], "a": 0, "sec": ["6.2"]}, {"id": "20-10", "ch": 20, "n": 10, "stem": "Quale reperto allo striscio di sangue è patognomonico della babesiosi?", "opts": ["Gametociti a forma di banana", "Granulazioni di Schüffner", "Tetradi di merozoiti a \"croce di Malta\"", "Spirochete tra i globuli rossi"], "a": 2, "sec": ["5.6"]}, {"id": "20-11", "ch": 20, "n": 11, "stem": "La terapia preferita per la babesiosi è:", "opts": ["Clorochina", "Atovaquone + azitromicina", "Artesunato", "Doxiciclina"], "a": 1, "sec": ["6.5"]}, {"id": "20-12", "ch": 20, "n": 12, "stem": "In un viaggiatore di ritorno dall'Africa orientale con episodi febbrili ricorrenti ogni settimana, il test diagnostico migliore è:", "opts": ["Sierologia per Lyme a due livelli", "Reazione di Weil-Felix", "Coprocoltura", "Striscio di sangue prelevato durante un episodio febbrile"], "a": 3, "sec": ["5.7"]}, {"id": "20-13", "ch": 20, "n": 13, "stem": "Poco dopo la prima dose di doxiciclina per una febbre ricorrente da zecche, il paziente sviluppa brividi scuotenti, febbre alta e ipotensione. Si tratta più probabilmente di:", "opts": ["Una reazione di Jarisch-Herxheimer", "Una reazione anafilattica alla doxiciclina", "Un fallimento terapeutico da resistenza", "Una coinfezione da virus della TBE"], "a": 0, "sec": ["6.6"]}, {"id": "20-14", "ch": 20, "n": 14, "stem": "Un cacciatore con tularemia polmonare e segni di sepsi deve essere trattato con:", "opts": ["Amoxicillina", "Azitromicina", "Gentamicina", "Ceftriaxone"], "a": 2, "sec": ["6.4"]}, {"id": "20-15", "ch": 20, "n": 15, "stem": "Il decorso tipico dell'encefalite da zecche causata dal sottotipo europeo è:", "opts": ["Febbre emorragica monofasica", "Bifasico: fase viremica simil-influenzale, intervallo asintomatico, poi fase neurologica", "Demenza cronica progressiva", "Febbre ricorrente ogni settimana per diversi mesi"], "a": 1, "sec": ["4.7"]}, {"id": "20-16", "ch": 20, "n": 16, "stem": "Quale affermazione sulla febbre emorragica Crimea-Congo è corretta?", "opts": ["È trasmessa solo dalle punture di zanzara", "Il bestiame infetto sviluppa di solito una grave malattia emorragica", "È stato dimostrato in studi randomizzati che la ribavirina riduce la mortalità", "Può verificarsi una trasmissione interumana attraverso sangue e liquidi biologici, anche in ospedale"], "a": 3, "sec": ["2.8", "6.8"]}, {"id": "20-17", "ch": 20, "n": 17, "stem": "Un paziente trattato correttamente per malattia di Lyme 1 anno fa lamenta astenia persistente e dolori diffusi. La sierologia è ancora positiva per le IgG. Che cosa è corretto?", "opts": ["Un'ulteriore terapia antibiotica prolungata non è raccomandata perché gli studi non hanno mostrato benefici", "È indicato un ciclo di 3 mesi di ceftriaxone e.v.", "La persistenza delle IgG dimostra un'infezione attiva", "La conta dei CD57 deve essere usata per guidare la terapia"], "a": 0, "sec": ["6.1"]}, {"id": "20-18", "ch": 20, "n": 18, "stem": "La doxiciclina in dose singola dopo una puntura di zecca è raccomandata quando:", "opts": ["Si verifica qualsiasi puntura di zecca, indipendentemente dalla specie", "La zecca risulta positiva per <em>Borrelia</em> alla PCR", "Una zecca <em>Ixodes</em> è rimasta attaccata per ≥36 ore in un'area altamente endemica e la profilassi può iniziare entro 72 ore dalla rimozione", "La sierologia per Lyme è positiva il giorno dopo la puntura"], "a": 2, "sec": ["8.2"]}, {"id": "20-19", "ch": 20, "n": 19, "stem": "Quale affermazione sui vaccini anti-TBE usati in Europa è corretta?", "opts": ["Sono vaccini vivi attenuati controindicati in tutti gli adulti", "Sono vaccini inattivati somministrati con un ciclo primario di 3 dosi seguito da richiami", "Una singola dose conferisce una protezione per tutta la vita", "Proteggono solo contro il sottotipo estremo-orientale"], "a": 1, "sec": ["8.4"]}, {"id": "20-20", "ch": 20, "n": 20, "stem": "Qual è il modo corretto di rimuovere una zecca attaccata?", "opts": ["Coprirla con vaselina e attendere che si stacchi", "Bruciarla con un fiammifero", "Schiacciarla a mani nude e svitarla", "Afferrarla vicino alla cute con pinzette a punta sottile e tirare verso l'alto con una pressione costante"], "a": 3, "sec": ["8.1"]}, {"id": "21-1", "ch": 21, "n": 1, "stem": "Quale dei seguenti virus NON è un flavivirus?", "opts": ["Virus dengue", "Virus West Nile", "Virus chikungunya", "Virus della febbre gialla"], "a": 2, "sec": ["1.1"]}, {"id": "21-2", "ch": 21, "n": 2, "stem": "In Italia, il principale vettore del virus West Nile è:", "opts": ["<em>Culex pipiens</em>", "<em>Aedes albopictus</em>", "<em>Phlebotomus perniciosus</em>", "<em>Culicoides paraensis</em>"], "a": 0, "sec": ["1.2"]}, {"id": "21-3", "ch": 21, "n": 3, "stem": "Il virus Toscana è trasmesso all'uomo da:", "opts": ["<em>Aedes albopictus</em>", "Zecche dure", "Zanzare <em>Culex</em>", "Flebotomi"], "a": 3, "sec": ["1.2"]}, {"id": "21-4", "ch": 21, "n": 4, "stem": "Quale meccanismo spiega meglio perché una seconda infezione da dengue con un sierotipo diverso comporta un rischio maggiore di malattia grave?", "opts": ["Distruzione diretta degli epatociti da parte dei linfociti T citotossici", "Potenziamento anticorpo-dipendente con aumento della viremia e disfunzione endoteliale", "Integrazione del genoma virale nelle cellule dell'ospite", "Produzione da parte del virus di un'esotossina simile a quelle batteriche"], "a": 1, "sec": ["3.2"]}, {"id": "21-5", "ch": 21, "n": 5, "stem": "Nella dengue, la fase critica con perdita di plasma si verifica tipicamente:", "opts": ["Nelle prime 24 ore di febbre", "Intorno allo sfebbramento, di solito tra il 3° e il 7° giorno", "Tre settimane dopo l'esordio della febbre", "Solo nelle infezioni primarie"], "a": 1, "sec": ["4.2"]}, {"id": "21-6", "ch": 21, "n": 6, "stem": "Quale dei seguenti è un segno d'allarme nella dengue?", "opts": ["Dolore retro-orbitario", "Esantema maculopapulare", "Mialgie", "Vomito persistente"], "a": 3, "sec": ["4.2"]}, {"id": "21-7", "ch": 21, "n": 7, "stem": "Quale caratteristica clinica aiuta di più a distinguere la chikungunya dalla dengue?", "opts": ["Poliartralgia grave, invalidante e simmetrica", "Marcata piastrinopenia con sanguinamento", "Perdita di plasma con shock", "Ittero con bradicardia relativa"], "a": 0, "sec": ["4.1", "4.3"]}, {"id": "21-8", "ch": 21, "n": 8, "stem": "La sindrome congenita da Zika comprende:", "opts": ["Dotto arterioso pervio e cataratta come caratteristiche principali", "Idrope fetale da anemia simil-parvovirus", "Microcefalia grave con calcificazioni sottocorticali e lesioni oculari", "Denti di Hutchinson e naso a sella"], "a": 2, "sec": ["4.4"]}, {"id": "21-9", "ch": 21, "n": 9, "stem": "Quale paziente ha il rischio più elevato di morte per malattia neuroinvasiva da West Nile?", "opts": ["Una donna sana di 25 anni", "Un bambino di 10 anni con asma", "Un uomo di 40 anni con ipertensione trattata", "Un uomo di 75 anni in terapia anti-CD20 per linfoma"], "a": 3, "sec": ["4.5"]}, {"id": "21-10", "ch": 21, "n": 10, "stem": "Il segno di Faget, tipico della febbre gialla, è:", "opts": ["Congiuntivite bilaterale non purulenta", "Febbre con bradicardia relativa", "Petecchie dopo il gonfiaggio di un bracciale per la pressione", "Paralisi flaccida di un arto"], "a": 1, "sec": ["4.6"]}, {"id": "21-11", "ch": 21, "n": 11, "stem": "Un viaggiatore di ritorno dalla Thailandia ha febbre da 2 giorni. Quale test è più appropriato per diagnosticare ora la dengue?", "opts": ["Antigene NS1 e/o RT-PCR su sangue", "Solo avidità delle IgG", "Solo test di neutralizzazione per riduzione delle placche", "Striscio di sangue per inclusioni da dengue"], "a": 0, "sec": ["5.2"]}, {"id": "21-12", "ch": 21, "n": 12, "stem": "Un uomo di 70 anni nel Lazio sviluppa un'encefalite in agosto. Quale risultato conferma meglio una malattia neuroinvasiva da West Nile?", "opts": ["IgG sieriche positive", "Emocoltura positiva", "Rilevamento di IgM specifiche per WNV nel liquor", "Lattato liquorale aumentato"], "a": 2, "sec": ["5.2"]}, {"id": "21-13", "ch": 21, "n": 13, "stem": "Un paziente precedentemente vaccinato contro la febbre gialla e l'encefalite da zecche ha IgM positive per West Nile. Qual è il problema principale?", "opts": ["Il risultato dimostra un'infezione acuta da tutti e tre i virus", "Le IgM non danno mai reazioni crociate tra i flavivirus", "Reattività crociata dei flavivirus; il risultato va confermato con un test di neutralizzazione", "Il paziente deve ricevere una nuova dose di vaccino contro la febbre gialla"], "a": 2, "sec": ["5.2"]}, {"id": "21-14", "ch": 21, "n": 14, "stem": "In un paziente con dengue sospetta, il farmaco raccomandato per febbre e dolore è:", "opts": ["Paracetamolo", "Ibuprofene", "Aspirina", "Ketorolac"], "a": 0, "sec": ["6.1"]}, {"id": "21-15", "ch": 21, "n": 15, "stem": "Secondo le linee guida attuali, quale intervento NON è raccomandato nella dengue grave?", "opts": ["Liquidi cristalloidi", "Tempo di riempimento capillare per guidare la terapia infusionale", "Misurazione del lattato", "Trasfusione profilattica di piastrine in un paziente senza sanguinamento"], "a": 3, "sec": ["6.1"]}, {"id": "21-16", "ch": 21, "n": 16, "stem": "In un paziente con insufficienza epatica da febbre gialla, le linee guida attuali suggeriscono:", "opts": ["Paracetamolo ad alte dosi", "N-acetilcisteina per via endovenosa", "Corticosteroidi sistemici", "Immunoglobuline per via endovenosa"], "a": 1, "sec": ["6.1"]}, {"id": "21-17", "ch": 21, "n": 17, "stem": "A settembre una donna rientra a Bologna da Cuba con febbre ed esantema, e si sospetta una dengue. Oltre alla notifica, quale misura è più importante per prevenire la trasmissione locale?", "opts": ["Isolamento in una stanza a pressione negativa", "Protezione dalle punture di zanzara durante la fase viremica, più controllo dei vettori attorno alla sua abitazione", "Profilassi antibiotica per i conviventi", "Vaccinazione immediata di tutti i suoi contatti"], "a": 1, "sec": ["5.5", "7.5"]}, {"id": "21-18", "ch": 21, "n": 18, "stem": "Quale affermazione sul vaccino contro la febbre gialla è corretta?", "opts": ["È un vaccino inattivato sicuro in tutti i pazienti immunocompromessi", "Deve essere ripetuto ogni 10 anni per tutti i viaggiatori", "È raccomandato nei lattanti di 3 mesi", "Una dose singola conferisce protezione per tutta la vita nella maggior parte delle persone"], "a": 3, "sec": ["8.3"]}, {"id": "21-19", "ch": 21, "n": 19, "stem": "Perché il vaccino CYD-TDV (Dengvaxia) viene somministrato solo alle persone con precedente infezione da dengue?", "opts": ["Nei sieronegativi aumenta il rischio di dengue grave in una successiva infezione naturale", "È inefficace nelle persone che hanno già avuto la dengue", "Contiene un adiuvante batterico pericoloso nei sieronegativi", "Causa la chikungunya nei sieronegativi"], "a": 0, "sec": ["8.3"]}, {"id": "21-20", "ch": 21, "n": 20, "stem": "Quale vaccino contro la chikungunya è un vaccino non vivo a particelle simil-virali?", "opts": ["Ixchiq (VLA1553)", "Qdenga (TAK-003)", "Vimkunya", "Ixiaro"], "a": 2, "sec": ["8.3"]}];
